window.ISG_EXTRA_TEMPLATES = [{"templateId":"isg_ofisler_kontrol","title":"OFİSLER İÇİN KONTROL LİSTESİ","runningHeader":"OFİSLER İÇİN KONTROL LİSTESİ","shortName":"Ofisler İçin Kontrol Listesi (58 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"OFİS-01","dosyaNo":"İSG-KL-01","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"GENEL","subHeader":"","items":["Zemin kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplı ve iç zeminler düzenli olarak kontrol ediliyor mu?","Zemindeki çökme, erime vb. deformasyonlar giderilmiş mi?","Cam yüzeyler üzerinde kırık veya çatlak bulunmamakta ve uygun şekilde monte edilmiş mi?","Ofis içerisinde duvarlara monte edilmiş raflar, TV üniteleri veya diğer malzemeler çalışanların üzerine düşmeyecek şekilde sabitlenmiş mi?","Merdiven genişlikleri ve basamak yükseklikleri uygun olup merdivenler boyunca tırabzanlar mevcut mu?","Ofis içerisinde kullanılan mobilyalar düzenli olarak kontrol ediliyor mu?","Ofiste temizlikten sorumlu kişi/kişiler belirlenmiş mi?","Çalışanlar, temizlikte kullanılan kimyasalların tehlikeleri ve kullanımı konusunda bilgilendirilmiş mi?","Temizlik yapılan alanda kaymayı önlemek için gerekli önlemler alınıyor mu?","Ofis içerisindeki tüm alanlar düzenli olarak havalandırılıyor mu?","İklimlendirme cihazlarının kontrolleri düzenli aralıklarla yapılıyor mu?","Ofis içerisindeki sıcaklık ve nemin, rahatsızlık vermeyecek düzeyde tutulması sağlanıyor mu?","Tüm alanlarda yeterli aydınlatma bulunuyor ve aydınlatmaların çalışır halde olması sağlanıyor mu?","Ofis içerisindeki çalışma alanlarında sigara içilmesi yasaklanmış ve çalışanlar bu konuda bilgilendirilmiş mi?","Çay, kahve, yemek vb. ihtiyaçların çalışma alanlarından ayrı bir yerde giderilmesi sağlanıyor mu?"]},{"title":"TERTİP - DÜZEN","subHeader":"","items":["Çalışanlar, işlerini bitirdikten sonra bütün malzemeleri yerlerine yerleştiriyorlar mı?","Ofis içerisindeki yerleşim, çalışanların faaliyetlerini kısıtlamayacak şekilde tasarlanmış ve uygulanmış mı?","Ofiste kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde bulunduruluyor mu?"]},{"title":"ELEKTRİK","subHeader":"","items":["Kaçak akım rölesi ana elektrik hattına bağlanmış mı?","Tüm sigortaların korunaklı yerlerde olması sağlanmış mı?","Sabit kurulumlar ve tesisatın düzenli bakımı yetkili kişiler tarafından yapılıyor mu?","Elektrik/sigorta kutuları kilitlenmiş, yetkisiz kişilerin erişimleri önlenmiş mi?","Açıkta kablo bulunmamakta, prizlerin sağlamlığı düzenli olarak kontrol edilmekte mi?","Kağıt vb. kolay tutuşabilir malzemeler, kıvılcım yayabilecek cihaz/ekipman/cisimlerden uzakta muhafaza ediliyor mu?"]},{"title":"MAKİNALAR","subHeader":"","items":["Elektrikli alet/ekipmanlar, üreticilerce sağlanan Türkçe kullanım kılavuzlarında belirtilen hususlara uygun şekilde kullanılıyor mu?","Elektrikli ekipmanlar düzenli olarak kontrol ediliyor, bozuk veya arızalı ekipmanların kullanımı engelleniyor mu?","Çalışanlar, elektrikli aletlerin güvenli kullanımları ile ilgili bilgilendirilmişler mi?"]},{"title":"ASANSÖRLER (Ofis/büronun bir yapının tümünde faaliyet göstermesi halinde)","subHeader":"","items":["Asansörler düzenli olarak kontrol ediliyor ve periyodik bakımları yapılıyor mu?","Asansör içi ve önü aydınlatmaları yeterli düzeyde mi?","Asansör makine dairesine yetkisiz kişilerin girişi engelleniyor mu?","Asansör içerisinde bulunan havalandırma sisteminin çalışıp çalışmadığı düzenli aralıklarla kontrol ediliyor mu?"]},{"title":"YANGIN (Ofis/büronun bir yapının tümünde faaliyet göstermesi halinde)","subHeader":"","items":["Yangın merdiveni kapıları/apartman kapısı/acil çıkışlar kilitli olmayıp her an açılabilir durumda mı?","Yangın merdiveni kapıları/apartman kapısı/acil çıkış kapıları dışarıya doğru açılıyor mu?","Yangın merdiveni kapıları/apartman kapısı/acil çıkışların önünde ve tüm yol boyunca kaçışı engelleyecek bir malzeme bulunmaması sağlanıyor mu?","Kapı ve kaçış yollarını gösteren acil durum levhaları uygun yerlere yerleştirilmiş, yangın merdiveninde ışıklandırma sağlanmış mı?","Yangın söndürücüleri mevcut ve son kullanma tarihleri kontrol ediliyor mu?","Acil duruma neden olan olaya ilişkin (yangın, gaz kaçağı, deprem vb.) telefon numaraları görünür yer(ler)e asılmış mı?","Acil durumlar ile ilgili iletişime geçilecek telefon numaraları (yangın, ambulans, polis vb.) ofis içerisinde görünür bir yere asılmış mı?"]},{"title":"GÜRÜLTÜ","subHeader":"","items":["Ofis içerisinde insanlardan, makine veya donanımlardan kaynaklanabilecek veya dış ortam kaynaklı gürültünün rahatsız edici düzeyde olmaması sağlanmış mı?"]},{"title":"ELLE TAŞIMA","subHeader":"","items":["Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engelleniyor mu?","Yüklerin elle taşınmasının da neden olabileceği kas iskelet sistemi hastalıklarına karşı çalışanlar bilgilendirilmiş mi?"]},{"title":"EKRANLI ARAÇLARLA ÇALIŞMA","subHeader":"","items":["Ofiste kullanılan ekranlı araçlar uygun yerlere yerleştirilmiş mi?","Ekranlı araçların veya diğer ekipmanların uzun süreli kullanımından kaynaklanabilecek kas iskelet sistemi hastalıklarına karşı gerekli önlemler alınıyor mu?"]},{"title":"ERGONOMİ ve MONOTON ÇALIŞMA","subHeader":"","items":["Çalışanların uzun süre aynı pozisyonda veya fiziksel anlamda zorlayıcı çalışmaları (ağır yük kaldırma dahil) engelleniyor mu?","Çalışanlara yaptıkları işe uygun masa, sandalye veya destek ekipmanları sağlanıyor mu?","Fazlaca yukarıya uzanmayı veya aşağıya eğilmeyi gerektiren işlerde çalışanların uzun süre hareketsiz aynı pozisyonda kalması engelleniyor mu?"]},{"title":"PSİKOSOSYAL ETKENLER","subHeader":"","items":["Çalışanlar, maruz kalabilecekleri olumsuz davranışlar (tehdit, hakaret vs.) karşısında nasıl davranacaklarını biliyorlar mı?","Çalışanlar ile işveren(ler) arasında iyi bir iletişim sağlanıyor mu?","Ofiste yürütülen işler ile ilgili çalışanların görüşleri alınıyor ve işyerinde iş sağlığı ve güvenliğinin sağlanması hususunda katılımları destekleniyor mu?","Çalışanlar; yetki, sorumluluk ve çalışma hedeflerini net olarak biliyorlar mı?","Çalışanlara, görev ve sorumlulukları haricinde talimat verilmemesine dikkat ediliyor mu?"]},{"title":"KAZALAR ve HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş ve periyodik muayeneleri zamanında yaptırılıyor mu?","Çalışanların karşı karşıya kaldıkları kazalar ve işe bağlı hastalıklar Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Çalışanların karşı karşıya kaldıkları önceden olmuş kazalar veya işe bağlı hastalıklar incelenerek yeniden meydana gelmeleri önleniyor mu?","İçerisinde yeterli malzeme bulunan ilkyardım çantası temin edilmiş mi?"]},{"title":"EĞİTİM ve BİLGİLENDİRME","subHeader":"","items":["Çalışanlara (çıraklar ve genç çalışanlar da dahil olmak üzere) genel iş sağlığı ve güvenliği eğitimi verilmiş mi?","Çalışanlar, yaptıkları iş konusunda eğitilmiş ve yönlendirilmiş mi?","Çalışanlar, özellikle kas iskelet sistemi hastalıklarından korunma konusunda bilgilendirilmiş mi?"]}]},{"templateId":"isg_ozel_guvenlik_kontrol","title":"ÖZEL GÜVENLİK FAALİYETLERİ İÇİN KONTROL LİSTESİ","runningHeader":"ÖZEL GÜVENLİK FAALİYETLERİ İÇİN KONTROL LİSTESİ","shortName":"Özel Güvenlik Faaliyetleri Kontrol Listesi (65 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"GÜV-01","dosyaNo":"İSG-KL-02","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"ÖZEL GÜVENLİK BÜROLARI VE ÖZEL GÜVENLİK GÖREVLİLERİNİN HİZMET VERDİĞİ ALANLAR İÇİN GENEL DURUMLAR","subHeader":"","items":["Özel güvenlik büroları ve hizmet verilen alanlarda zemin, kayma veya düşmeyi önleyecek şekilde tasarlanmış mıdır?","Özel güvenlik büroları ve hizmet verilen alanlardaki tüm cam yüzeyler uygun şekilde monte edilmiş midir? Yüzeyler üzerinde kırık veya çatlak bulunmakta mıdır?","Özel güvenlik büroları içerisinde duvarlara monte edilmiş raflar, TV üniteleri veya diğer malzemeler çalışanların üzerine düşmeyecek şekilde sabitlenmiş midir?","Özel güvenlik büroları ve hizmet verilen alanlarda yeterli aydınlatma sağlanmış mıdır ve aydınlatmalar çalışır halde bulunmakta mıdır?","Özel güvenlik büroları ve hizmet verilen alanlardaki kapalı mekânlar düzenli olarak havalandırılmakta mıdır?","Özel güvenlik büroları ve hizmet verilen alanlarda; insanlardan, makine veya donanımlardan kaynaklanabilecek veya dış ortam kaynaklı gürültü rahatsız edici düzeyde midir?","Özel güvenlik bürolarındaki ve hizmet verilen alanlardaki mevcut iklimlendirme cihazlarının kontrolleri düzenli aralıklarla yaptırılmakta mıdır?","Özel güvenlik hizmeti verilen alanlarda, özel güvenlik görevlisinin yeme-içme, barınma gibi temel ihtiyaçları için uygun donanımlı alanlar ayrılmış mıdır?","Özel güvenlik hizmeti verilen yüksek riskli çalışma alanlarında kapalı devre kamera sistemi kurulmuş mudur?"]},{"title":"ÖZEL GÜVENLİK FAALİYETLERİNE BAĞLI ÖZEL DURUMLAR","subHeader":"","items":["Özellikle hastaneler, alışveriş merkezleri gibi özel güvenlik hizmeti verilen çok hareketli yerlerde özel güvenlik görevlisinin can güvenliğini sağlayacak güvenlik tedbirleri (şifreli kapılar, girişler vb.) alınmış mıdır?","Özel güvenlik görevlisinin diğer kişilerle (meslektaşı, genel kolluk kuvveti, işvereni vb.) anında ve hızlı haberleşme imkanı (telefon, telsiz, alarm sistemi gibi) sağlanmış mıdır?","Haberleşme cihazlarının kolay ulaşılabilir olması sağlanmış mıdır ve bu cihazların çalışır durumda olduğu sıkça kontrol edilmekte midir?","Özel güvenlik görevlilerinin yalnız çalıştırılmasından mümkün olduğu ölçüde kaçınılmakta mıdır?","Köpekli korumanın sağlandığı yerlerde bu hayvanların sağlık durumu düzenli olarak izlenmekte midir, ağızlık ve burunluk kullanımı ile ilgili kurallara uyulmakta mıdır?","Silahlı korumanın sağlandığı yerlerde bulundurulan silahlar uygun ortamlarda muhafaza edilmekte midir ve bakımları uzman personel tarafından düzenli olarak yapılmakta mıdır?","Özel güvenlik görevlisine tahsis edilen silah/mühimmatlara ilişkin uygunsuz durumlar ilgili birimlere iletilmekte midir, kişi, silahın muhafazası ile ilgili kurallara uymakta mıdır, silahın başka şahısların eline geçmesini önleyecek tüm tedbirleri almakta mıdır?","Özel güvenlik hizmeti verilen açık alanların çevresinde çalışanı yaralayabilecek nitelikte kayma ve düşmelerin olabileceği alanlar belirlenmiş midir ve gerekli önlemler alınmış mıdır?"]},{"title":"ASANSÖRLER (özel güvenlik büroları ve özel güvenlik görevlilerinin hizmet verdiği alanlarda mevcut ise)","subHeader":"","items":["Özel güvenlik büroları ve hizmet verilen alanlardaki asansörlerin kontrolleri ve periyodik bakımları düzenli olarak yapılmakta mıdır?","Özel güvenlik büroları ve hizmet verilen alanlardaki asansör içi ve önü aydınlatmaları yeterli düzeyde midir?","Özel güvenlik büroları ve hizmet verilen alanlardaki asansör içerisinde bulunan havalandırma sisteminin çalışıp çalışmadığı düzenli aralıklarla kontrol edilmekte midir?"]},{"title":"EKRANLI ARAÇLAR","subHeader":"","items":["Özel güvenlik bürolarında kullanılan ekranlı araçlar uygun yerlere yerleştirilmiş midir?","Ekranlı araçların veya diğer ekipmanların uzun süreli kullanımından kaynaklanabilecek kas iskelet sistemi hastalıklarına karşı gerekli önlemler alınmakta mıdır?"]},{"title":"MAKİNELER, EL ALETLERİ VE YARDIMCI EKİPMANLAR","subHeader":"","items":["Özel güvenlik bürolarında kullanılan makine/ekipmanlar için üretici firmadan, kullanım kılavuzları temin edilmiş midir ve makineler kılavuza uygun olarak kullanılmakta mıdır?","Özellikle hareketli parçaları olan makineler/aletler, üreticisinin talimatları doğrultusunda koruma panelleri vb. önlemler ile koruma altına alınmış mıdır?","İmalatçının talimatları doğrultusunda tüm makinelerin günlük bakımları ve periyodik kontrolleri yapılmakta mıdır?","Lazer ile çalışan cihaz, el aletleri ya da teknik aparatlar gerekli önlemler alınarak kullanılmakta mıdır?","Tarayıcılar veya X-ray cihazları özel eğitim almış çalışanlar tarafından ve gerekli önlemler alınarak kullanılmakta mıdır?","Dış alanlarda görev yapan devriyeler için yeterli sayıda el feneri bulundurulmakta mıdır?","Tarayıcı veya X-ray cihazları ile kontrol edilen bölgelere, uyarıcı panolar/güvenlik ve sağlık işaretleri yerleştirilmiş midir?"]},{"title":"KİŞİSEL KORUYUCU DONANIMLAR","subHeader":"","items":["Özel güvenlik görevlilerine atış esnasında kullanmak üzere; göz, kafa ve kulak koruyucular gibi kişisel koruyucu donanımlar sağlanmakta mıdır?","Özel güvenlik görevlilerine uygun iş kıyafeti ile ayakkabı temin edilmekte midir ve kullanılması sağlanmakta mıdır?","Açık alanda görev yapan özel güvenlik görevlileri için soğuğa veya güneş ışığına maruziyeti önleyecek/azaltacak giysi/ekipman temin edilmekte midir ve kullanılması sağlanmakta mıdır?"]},{"title":"ELLE TAŞIMA","subHeader":"","items":["Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engellenmekte midir?","Yüklerin elle taşınmasının da neden olabileceği kas iskelet sistemi hastalıklarına karşı çalışanlar bilgilendirilmiş midir?"]},{"title":"ERGONOMİ VE MONOTON ÇALIŞMA","subHeader":"","items":["Özel güvenlik görevlilerinin uzun süre aynı pozisyonda veya uzun süre hareketsiz çalışması engellenmekte midir?","Çalışanlara yaptıkları işe uygun sandalye veya destek ekipmanı sağlanmakta mıdır?"]},{"title":"YÜKSEKTE ÇALIŞMA","subHeader":"","items":["Zorunlu olmadığı durumlarda yüksekte çalışmaktan kaçınılmakta mıdır?","Özel güvenlik faaliyeti dışında kalan ve yüksekte çalışmayı gerektirecek riskli işler bu konuda eğitimli kişiler tarafından yapılmakta mıdır?"]},{"title":"ELEKTRİK","subHeader":"","items":["Açık bir şekilde elektrik tehlikesi bulunan alanlarda hizmet veren özel güvenlik görevlilerinin bu alanlardan uzak ve güvenli bir yerde çalışmaları sağlanmakta mıdır?","Özel güvenlik büroları ve hizmet verilen alanlarda elektrik/sigorta kutuları kilitlenmiş midir ve bu kutulara yetkisiz kişilerin erişimleri önlenmiş midir?","Özel güvenlik büroları ve hizmet verilen alanlarda tüm sigortaların korunaklı yerlerde olması sağlanmış mıdır?","Özel güvenlik büroları ve hizmet verilen alanlarda açıkta kablo bulunmakta mıdır? Prizlerin sağlamlığı düzenli olarak kontrol edilmekte midir?"]},{"title":"ACİL DURUMLAR VE YANGIN","subHeader":"","items":["Acil durumlar ile ilgili iletişime geçilecek telefon numaraları (yangın, ambulans, polis vb.) özel güvenlik büroları ve hizmet verilen alanlarda görünür yerlere asılmış mıdır?","Özel güvenlik büroları ve hizmet verilen alanlarda belirli yerlerde yangın söndürücüleri mevcut mudur, son kullanma tarihleri ve basınçları kontrol edilmekte midir?","İçerisinde yeterli malzeme bulunan ilkyardım çantası/dolabı, acil durumlar için kolay ulaşılabilir bir yerde bulundurulmakta mıdır?","Özel güvenlik büroları ve hizmet verilen alanlarda yangın merdivenine açılan acil çıkış kapıları kilitli midir ve bu kapılar dışa doğru açılacak şekilde tasarlanmış mıdır?","Özel güvenlik görevlileri yangın alarmları, kontrollü tahliye vb. konularda eğitilmiş midir?"]},{"title":"PSİKOSOSYAL ETKENLER VE STRES","subHeader":"","items":["Özel güvenlik görevlilerine, görev ve sorumlulukları haricinde talimat verilmekte midir?","Özel güvenlik görevlileri, maruz kalabilecekleri olumsuz davranışlar (tehdit, hakaret vs.) karşısında nasıl davranacağını bilmekte midir?","Silahlı koruma sağlayan özel güvenlik görevlileri için psikolojik testler yaptırılmakta mıdır?","Özel güvenlik görevlileri ile işveren(ler) arasında iyi bir iletişim sağlanmakta mıdır?","Özel güvenlik görevlileri, yaptıkları işten kaynaklanan stres ile baş edebilmeleri için gerekli eğitimi almışlar mıdır?","Özel güvenlik görevlilerinin çalışma programları belirlenmiş midir?"]},{"title":"KAZALAR ve HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş ve periyodik muayeneleri zamanında yaptırılmakta mıdır?","Çalışanların, gece vardiyası veya değişik vardiya çalışmalarına uyumlarındaki sorunlar izlenmekte midir ve bu çalışanlar düzenli sağlık gözetiminden geçirilmekte midir?","Çalışanların karşı karşıya kaldıkları kazalar ve işe bağlı hastalıklar Sosyal Güvenlik Kurumuna rapor edilmekte midir?","Çalışanların karşı karşıya kaldıkları önceden olmuş kazalar veya işe bağlı hastalıklar incelenerek yeniden meydana gelmeleri önlenmekte midir?","Tüm çalışanlara enfeksiyon riskini azaltmak için genel hijyen bilgisi ile bulaşıcı hastalıklardan korunmaları konusunda bilgi verilmiş midir?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Çalışanlar, yaptıkları iş konusunda eğitilmiş ve yönlendirilmiş midir?","Özel güvenlik görevlileri, olaylar karşısında verilen talimat ve alınan eğitim doğrultusunda hareket etmekte midir?","Silahlı koruma hizmeti sunan özel güvenlik görevlileri, silahlarını, alınan eğitim ve verilen talimatlara uygun olarak kullanmaları hususunda talimatlandırılmış mıdır?","Özel güvenlik görevlisinin hizmet sunduğu alanlardaki potansiyel tehlikeler, işyeri içerisindeki güvenli ulaşım yolları vb. konularda özel güvenlik görevlisi bilgilendirilmiş midir?","Çalışanlar, X Ray cihazlarının kullanılması konusunda eğitilmiş ve bu cihazların yanlış kullanımının neden olacağı riskler hakkında bilgilendirilmiş midir?","Özel güvenlik görevlileri işyerinde kişisel güvenlik konusunda eğitilmiş midir?","Çalışanlara genel iş sağlığı ve güvenliği eğitimi verilmiş midir?"]}]},{"templateId":"isg_mekanik_bakim_kontrol","title":"MEKANİK BAKIM İÇİN KONTROL LİSTESİ","runningHeader":"ARAÇ TAMİRHANELERİ İÇİN KONTROL LİSTESİ","shortName":"Mekanik Bakım Kontrol Listesi (87 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"BKM-01","dosyaNo":"İSG-KL-03","sayfaNo":"1-N","actionHeaderLabel":"Uygun Değilse Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"GENEL","subHeader":"","items":["Zemin kayma veya düşmeyi önleyecek şekilde uy ile kaplanmıştır ve iç ve dış zeminler düzenli olar edilmektedir.","Merdiven genişlikleri ve basamak yükseklikleri u","Çalışma alanlarında dökülen malzemeler veya di sebeplerden ötürü kayganlaşan zeminler ya da g temizlenmektedir.","Forklift vb. araçların kullanıldığı çalışma alanların araçlarla çalışmaya uygundur.","Müşteriler için önceden yer ayırtmaksızın güven edebilecekleri alanlar sağlanmıştır.","Tesis çevresinde araçların uygun hızda seyretme amacı ile gerekli önlemler alınmıştır.","Tesiste içme suyu bulunmaktadır.","Çalışanlar için soyunma odası mevcuttur.","Çalışanların için yemek yeme yeri mevcuttur."]},{"title":"TERTİP - DÜZEN","subHeader":"","items":["Çalışma alanları temiz ve herhangi bir kazaya ma vermeyecek şekilde düzenlidir.","Çalışma ortamında, hastalıklara sebebiyet verere devamsızlığa neden olabilecek koşullar yoktur.","Depolama alanları araçların güvenli yükleme ve yapabileceği ve yayaların güvenli geçişini sağlaya düzenlenmiştir.","Tuvalet ve lavabolar günlük olarak temizlenmekt"]},{"title":"AYDINLATMA","subHeader":"","items":["Çalışma alanlarında ışık yeterlidir.","Aydınlatma armatürlerinden / donanımlarından pencerelerden kaynaklanan göz kamaştırıcı parıl oluşturduğu riskler önlenmiştir.","Tüm merdiven ve yürüme yollarındaki aydınlatm halde bulunmaktadır."]},{"title":"ELEKTRİK","subHeader":"","items":["Kaçak akım rölesi elektrik hattına bağlanmıştır.","Elektrik tesisatının periyodik bakımları yetkin kiş programına uygun şekilde yapılmaktadır.","Çalışanlar hasar görmüş herhangi bir elektrik aks karşılaşmaları durumda ne yapmaları gerektiği il bilgilendirilmiştir.","Acil durumlar oluşması durumunda çalışanlar ele tesisatının ne şekilde kapatılacağı ile ilgili bilgilen","Elektrik/sigorta kutuları kilitlenmiş, yetkisiz kişile önlenmiştir.","Tüm sigortaların korunaklı yerlerde olması sağla","Sigorta kutusu kolayca erişilebilir durumdadır.","Açıkta kablo bulunmamakta, prizlerin sağlamlığı edilmektedir.","Çalışmalar sırasında güvenlik ve sağlık işaretleri v kullanılmaktadır.","Aküler şarj edilirken yetkin bir elektrikçi tarafınd tescilli şarj cihazı kullanılmaktadır.","El feneri vb. cihazlar düşük voltajda çalışmaktadı","380 V ile çalışan cihazların hepsinde endüstriyel bulunmaktadır.","380 V ile çalışan cihazların bakımları yapılmakta arızaları bildirmektedir.","Kurulu ekipmanların düzenli olarak bakımları yap"]},{"title":"MAKİNELER, EL ALETLERİ VE DİĞER TEKNİK ARAÇLAR-GEREÇLER","subHeader":"","items":["Tüm makinelerin acil durdurma tertibatı bulunm","Tüm makineler için, makinelerin kullanımı ve bak hususunda Türkçe olarak hazırlanmış kullanım kı mevcuttur.","Makinelerin bakımı imalatçının talimatları doğru yapılmıştır.","Çalışanlar kompresör gibi cihazların güvenli kulla konusunda eğitilmiş ve bu cihazların kullanımı sı şakalaşılmaması gerektiği hususunda tembihlenm","Basınçlı hava hattında kullanıcının bilincini kaybe durumunda sistemi kapatacak bir hata koruma s bulunmaktadır. (deadman’s switch)","Forklift vb. araçlar bu konuda eğitim almış çalışa tarafından kullanılmaktadır.","Forkliflerin periyodik bakımları yapılmaktadır.","Tüm el aletleri ve teknik araç-gereçler için, bunla ve bakımı hususunda Türkçe olarak hazırlanmış k kılavuzu mevcuttur.","Ekipmanlar düzgün çalışmaktadır ve bakımları ya","Bütün cihazlar kullanılmadan önce kontrol edilm","Çalışanlar kullandıkları teçhizatları çalışır halde bırakmamaktadır."]},{"title":"HAVA YASTIKLARI","subHeader":"","items":["Hava yastıkları uygun depolama alanlarında bulu","Çalışanlar hava yastıklarının doğru taşınması ve y konusunda eğitilmiştir.","Kusurlu hava yastıkları imha edilmesi amacıyla ü edilmektedir."]},{"title":"YANGIN","subHeader":"","items":["Yangın ile ilgili yapılan risk değerlendirmesi sonu önlemlerin uygulanmasını sağlamak amacıyla pe kontroller gerçekleştirilmektedir.","Binada, Binaların Yangından Korunması Hakkınd uyarınca tüm önlemler alınmıştır.","Yangın merdiveni kullanılabilir durumdadır.","Yangın merdiveni kapıları/acil çıkışlar kilitli değild açılabilir durumdadır.","Yangın merdiveni kapıları/acil çıkışların önünde v boyunca kaçışı engelleyecek bir malzeme yoktur","Yangın merdiveni kapıları/acil çıkış kapıları dışarı açılmaktadır.","Acil durum ışıklandırması tesis edilmiştir.","Kapı ve kaçış yollarını gösteren acil durum levha yerlere yerleştirilmiş, yangın merdiveninde ışıkla sağlanmıştır.","Yangın söndürücüleri mevcuttur ve son kullanma kontrol edilmektedir.","Çalışanlar yangın tüplerinin kullanımı konusunda almıştır.","Yangın, doğal afetler vb. hallerde görev paylaşım ve ilan edilmiştir.","Acil durum planı hazırlanmış ve görünür bir yere","Sigara içilmesi bütün çalışma alanlarında yasakla","Yangın alarmlarının bakımı ve kontrolü üretici ta gerçekleştirilmiştir.","Dökülen ya da sıçrayan yakıt derhal temizlenmek","LPG yakıtlı araçlar güvenli ortamlarda bulunduru","Çalışanlar yakıtlar ve LPG ile çalışma konusunda bilgilendirilmiştir."]},{"title":"YÜKSEKTE ÇALIŞMA","subHeader":"","items":["Seyyar merdivenler yapısal olarak sağlamdır, düz kontrol edilmektedir ve sadece uygun donanım i çalışanlar tarafından kısa süreler için kullanılmak","Seyyar merdivenler kullanılırken sabitlenmekted"]},{"title":"KİMYASAL MADDELER","subHeader":"","items":["Çalışanlar kullanılan kimyasallar ve etkileri konus bilgilendirilmiştir.","Kimyasalların üzerinde uygulama yöntemi, kullan koruyucu donanım ve bu maddelerin zararlarını etiketler bulunmaktadır.","Araba motorunun kapalı alanlarda çalıştırılması arabanın egzozu aspiratör sistemine bağlanmakt","Aspiratör sisteminin bakımı düzenli olarak yapılm tutulmaktadır.","Çalışanlar, kimyasal maddeler ile çalışma sırasınd solunum vb. temasını önleyecek şekilde uygun n koruyucu donanımları (eldiven, maske vb.) kulla","İş tulumları düzenli olarak temizlenmektedir.","Aküler şarj edilirken aside dayanıklı gözlük ve eld kullanılmaktadır."]},{"title":"SICAKLIK","subHeader":"","items":["Atölyede kış boyunca kullanılacak taşınabilir ısıtı mevcuttur."]},{"title":"GÜRÜLTÜ","subHeader":"","items":["Gürültünün yüksek olduğu ortamlarda işitme ko kullanılmaktadır."]},{"title":"KAYMA, DÜŞME","subHeader":"","items":["Merdivenlerin açıkta kalan bölümlerinde yeterli yükseklikte ve korkuluğun üst ve orta kısımlarınd tutunma yeri ve gerekli ise eteklik bulunan korku mevcuttur.","1,8 m. 'den geniş olan merdivenlerin her iki yanı bulunmaktadır.","Elektrik kabloları takılıp düşmeye mahal vermey konumlandırılmıştır."]},{"title":"DÜŞEN CİSİMLER","subHeader":"","items":["Krikoların bakım ve onarımı yetkili kişiler tarafınd yapılmaktadır.","El krikoları sadece sağlam ve düz zeminlerde kul","Güvenli çalışma için konulan yük limitleri aşılmam","Araç kaldırma ekipmanının bakım ve onarımı dü yapılmaktadır."]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş muayeneleri ve periyodik ko yapılıyor mu?","Çalışanların karşı karşıya kaldıkları önceden olmu işe bağlı hastalıklar incelenerek yeniden meydan önlenmektedir.","Çalışanların, örneğin kısa devre nedeniyle, elektr neden olabilecek kadar tehlikeli akımlarla karşıla bulunmamaktadır.","Çalışanların işlerini kazaya mahal verecek derece yapması gereken durumlar bulunmamaktadır.","Çalışanların sıcak yüzeylerle ya da püsküren buh ederek yanma ya da haşlanma tehlikesi bulunma","İş kazaları ve meslek hastalıkları vakaları Sosyal G Kurumuna rapor ediliyor mu?"]},{"title":"EĞİTİM ve BİLGİLENDİRME","subHeader":"","items":["Çalışanlara (çıraklar ve genç çalışanlar dahil olma genel iş sağlığı ve güvenliği eğitimi verilmiştir.","Çalışanlar yaptıkları işle ilgili olarak genel anlamd bilgiye sahiptir."]}]},{"templateId":"isg_tekinak_uretim_kontrol","title":"TEKİNAK GIDA ÜRETİM FAALİYETLERİ İÇİN KONTROL LİSTESİ","runningHeader":"TEKİNAK GIDA ÜRETİM FAALİYETLERİ İÇİN KONTROL LİSTESİ","shortName":"Tekinak Gıda Üretim Kontrol Listesi (162 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"BANNER","formNo":"ÜRT-01","dosyaNo":"İSG-KL-04","sayfaNo":"1-N","actionHeaderLabel":"ALINMASI GEREKEN ÖNLEM","dueDateHeaderLabel":"TAMAMLANMA TARİHİ","footnote":"","sections":[{"title":"TEHLİKELER (Yüksekte Çalışma)","subHeader":"","items":["Yüksekte çalışmayı gerektiren durumlarda çalışma yerlerine uygun araç ve ekipman ile çıkılması sağlanmaktadır.","Merdivenler, yükseltilebilen seyyar iş platformları uçakta çalışılacak alan ile arasında boşluk kalmayacak şekilde konumlandırılmıştır.","Merdiven basamakları ve platformlarda çatlak, göçük vb. deformasyonlar, engeller bulunmamaktadır.","Merdivenlerin, yükseltilebilen seyyar iş platformlarının korkulukları bulunmaktadır ve bakımlıdır.","Merdivenler üzerinde çalışma yapılırken hareket ettirilmemektedir.","Merdiven ve yükseltilebilen seyyar iş platformları çalışmalar esnasında yere sabitlenmektedir.","Merdiven ve yükseltilebilen seyyar iş platformlarının sabitleme mekanizmaları hasarlı değildir, bakımları yapılmaktadır.","Merdivenlerin ayakları kaymayı önleyici malzeme ile kaplanmıştır ve bakımlıdır.","Merdiven ve yükseltilebilen seyyar iş platformlarının azami yük kapasiteleri işaretlenmiştir ve kapasiteleri aşılmamaktadır.","Önünde platform olmayan açık kapılara güvenlik şeridi çekilerek çalışanlar düşmeye karşı uyarılmıştır.","Merdiven basamak yükseklikleri uygundur ve çalışma platformları yeterli genişliktedir.","Çalışma platformları boyunca malzemelerin düşmesini engelleyecek tekmelikler bulunmaktadır.","Düşmelerini önlemek amacıyla el aletleri için sabitlenmiş, korunaklı bir yer yapılmıştır. İşi biten el aletleri platformda bırakılmamaktadır.","Çalışanlar, platformlarda yüksekten düşmeye karşı emniyet kemeri, kanatlarda yada uçağın üst yüzeyinde yapılan çalışmalarda ise vakumlu kit gibi kişisel koruyucu donanımlar kullanmaktadır."]},{"title":"MEKANİK TEHLİKELER (Yükseltilebilen Seyyar İş Platformları İle Çalışma)","subHeader":"","items":["Yükseltilebilen seyyar iş platformlarının hangar içerisinde kullanılırken hız limitinin aşılması engellenmiştir.","Yükseltilebilen seyyar iş platformlarının hangar içerisinde ileri-geri manevrası sırasında diğer araçlarla ve çalışanlarla çarpışmalarının önlenmesi amacıyla sesli ve ışıklı uyarı sistemleri çalışmaktadır.","Yükseltilebilen seyyar iş platformlarının yukarı-aşağı hareketi sırasında uzuv sıkışmalarının önlenmesi amacıyla sesli ve ışıklı uyarı sistemleri çalışmaktadır.","Yükseltilebilen seyyar iş platformlarının uçağa belli bir yakınlığa ulaşması durumunda yerde bulunan bir gözlemci tarafından yönlendirilmesi sağlanmaktadır.","Yükseltilebilen seyyar iş platformları kapasitesinden fazla yüklenmemektedir.","Yetkisiz kişilerce araçların kullanımı engellenmektedir.","Yükseltilebilen seyyar iş platformlarının periyodik bakımları yapılmaktadır.","Yükseltilebilen seyyar iş platformlarının kullanımları konusunda çalışanlara eğitim verilmektedir.","Araç kullanım talimatları üzerlerinde yazılı olarak bulundurulmaktadır.","Yükseltilebilen seyyar iş platformları sadece kendilerine ayrılan alanda amacına uygun kullanılmaktadır."]},{"title":"MEKANİK TEHLİKELER (Kayma-Takılma-Düşme)","subHeader":"","items":["Fabrika alanı zemini kaymayı önleyici uygun malzeme ile kaplanmıştır ve düzenli olarak kontrol edilmektedir.","Zeminde çökme, erime vb. deformasyonlar bulunmamaktadır.","Zeminde kaldırılması mümkün bulunmayan pürüzler ve engebeler dikkat çekecek şekilde işaretlenmiştir.","Zeminde takılmaya neden olabilecek kablolar ve hortumlar bulunmamaktadır.","Zeminde bulunan eşik ve benzeri seviye değişiklikleri dikkat çekecek şekilde işaretlenmiştir.","Zemine sıçrayan veya dökülen tüm malzeme ve sıvılar derhal temizlenmektedir.","Motordan zemine hidrolik yağı damlamasına karşı damlatma tavası kullanılmaktadır.","İşin özelliği gereği ıslanan zemine uygun uyarıcı levhalar konulmaktadır.","Merdiven ve platformlarda kaymaya neden olabilecek ıslaklıklar bulunmamaktadır.","Merdiven ve platformlarda takılmaya neden olabilecek kullanılmayan malzemeler derhal kaldırılmaktadır.","Çalışanların kayma ve düşmeyi önleyecek uygun iş ayakkabıları kullanmaları sağlanmıştır."]},{"title":"MEKANİK TEHLİKELER (Makine ve İş Ekipmanlarının Kullanımı)","subHeader":"","items":["Makine ve iş ekipmanlarının koruyucuları mevcuttur ve hasarsızdır.","Makine ve iş ekipmanlarının koruyucuları olmadan çalıştırılmamaktadır.","Hasarlı makine ve iş ekipmanlarının kullanımı engellenmektedir.","Makine ve iş ekipmanlarının acil durdurma düğmeleri çalışanların uzanabileceği konumda ve çalışır durumdadır.","Makine ve iş ekipmanlarının periyodik bakımları yapılmaktadır.","Makinelerin etrafında çalışma için yeterli alan mevcuttur.","Makine ve iş ekipmanlarının kullanımı ile ilgili çalışanlara eğitim verilmektedir.","Makine ve iş ekipmanları ile çalışırken uygun kişisel koruyucu donanım (gözlük, eldiven, kulak koruyucu)kullanılmaktadır.","Makine ve iş ekipmanlarının güç kaynağından bağlantısı kesilmeden takım değiştirilmemektedir.","Makine ve iş ekipmanlarının Türkçe kullanma kılavuzları mevcuttur.","Makine ve iş ekipmanları kullanma kılavuzlarına uygun şekilde kullanılmaktadır.","Tüm alet ve ekipmanlar tasarım amaçlarına uygun kullanılmaktadır.","Kesici veya delici nitelikteki el aletlerinin açıkta bulundurulması engellenmektedir ve koruyucu içerisinde muhafaza edilmesi sağlanmaktadır.","Tüm makine ve ekipmanlarda gerekli uyarı işaretleri bulunmaktadır.","Makine ve iş ekipmanlarını yetkisiz kişilerin kullanması engellenmektedir."]},{"title":"FİZİKSEL TEHLİKELER (Gürültü)","subHeader":"","items":["Gürültü düzeyi uyarı ve tehlike sinyallerini baskılayacak düzeyde değildir.","Motor, hidrolik, pnömotik, rat testleri başlayacağı zaman uyarıcı sesli sinyaller verilerek çalışanların kulak koruyucularını kullanmaları sağlanmaktadır.","Mevzuatta belirtilen gürültü seviyesinin üzerinde olan makine ve iş ekipmanları ile çalışmalarda kulak koruyucusu kullanılmaktadır.","Gürültülü ortama girmesi gereken çalışanların kulak koruyucusu takmadan girmeleri engellenmektedir.","Gürültünün direkt yayılımı perdeleme ya da bariyerlerle engellenmektedir.","Gürültü emisyonunu azaltacak mühendislik yöntemleri( titreşen makine ya da bileşenlerinin yalıtımı, havalandırma sistemlerinde susturucular kullanılması vb. ) uygulanmaktadır.","Kulak koruyucularının bakımı ve uygun şekilde muhafazası sağlanmaktadır.","Rotasyonlu çalışma yaptırılarak çalışanların gürültüye maruz kalma süreleri azaltılmaktadır."]},{"title":"FİZİKSEL TEHLİKELER (Aydınlatma)","subHeader":"","items":["Gün ışığının yetmediği işlerde suni ışıklandırma sağlanmaktadır.","Kapalı alanlarda(Yakıt tankı vb.) çalışmalarda işin özelliğine uygun yeterli aydınlatma sağlanmaktadır.","Çalışma alanlarında işin etkinliğini ve doğru bir şekilde yapılmasını etkileyebilecek gölgeler oluşmamaktadır.","Suni aydınlatma gölge ve yansıma oluşturmayacak şekilde konumlandırılmaktadır.","Tüm alanlarda aydınlatmalar çalışır halde bulunmaktadır.","Çalışma alanları ve geçiş yolları uygun bir şekilde aydınlatılmıştır.","Aydınlatma sisteminin devre dışı kalmasının çalışanlar için risk oluşturabileceği yerlerde yeterli aydınlatmayı sağlayacak ayrı bir enerji kaynağına bağlı acil aydınlatma sistemi bulunmaktadır."]},{"title":"FİZİKSEL TEHLİKELER (Elektromanyetik Alan)","subHeader":"","items":["Makarma hatları çalışması sırasımnda alandaki ısı.","Çalışanlara elektromanyetik alan maruziyeti ve etkileri konularında eğitimler verilmektedir."]},{"title":"KİMYASAL TEHLİKELER","subHeader":"","items":["Tehlikeli kimyasal maddeler (zehirli, aşındırıcı, tahriş edici, kanserojen, m kullanılmamaktadır.","Kimyasallara ait güncel malzeme güvenlik bilgi formları mevcuttur ve çalışanla erişimine açıktır.","Tehlikeli kimyasal mümkün ise daha az tehlikeli olanı ile ikame edilmektedir.","Kimyasallar etiketli olarak muhafaza edilmektedir.","Kimyasalların depolandığı alanda yeterli havalandırma sağlanmaktadır.","Kimyasal atıklar uygun şekilde depolanmaktadır ve imha edilmektedir. Tüm sol artıkları ve alev alıcı kimyasallar çalışma alanından çıkarılıncaya kadar dayanıklı, kapalı variller içinde saklanmaktadır.","Bütün tehlikeli kimyasallar ağzı kapalı şekilde bulundurulmaktadır ve taşınmakt","Kimyasalların izin verilen azami konsantrasyon miktarları hangarda bulunan ölçülerek kontrol altında tutulmaktadır.","Boyama kabininde kimyasal konsantrasyonunun artmasına karşılık yerel havala bulunmaktadır.","Hidrolik test öncesinde verilen sesli ikaz ile çalışanlar uyarılarak, hidrolik maruziyetine bağlı riskler engellenmektedir.","Yakıt tankına, içerisindeki hava miktarı ölçülerek girilmektedir. Oksijen m düzeyi ve duman, gaz vb. tehlikeler sürekli izlenmektedir.","Yakıt tankında çalışmalarda uygun solunum koruyucu ve diğer kişisel ko ekipmanlar kullanılmaktadır.","Tozlu odada yeterli lokal havalandırma sistemi bulunmaktadır.","Bina içinde kullanılan motorlu araçlardan yayılan karbon monoksit seviyesi aza kabul edilebilir seviyesinin altındadır ve ek havalandırma önlemleri alınmıştır.","Kimyasalların kullanıldığı alanda genel havalandırma ve yerel havalan sağlanmıştır. Filtrelerinin periyodik kontrolü ve değişimi yapılmaktadır.","Çalışanlar için kimyasalların kullanıldığı yerlerde işin özelliğine uygun koruyucu ekipman (eldiven, gözlük, yüz siperi, maske vb.) sağlanmıştır.","Çalışanlara kimyasalların kullanımı, tehlikeleri ve taşınması konularında verilmektedir.","Kimyasallar ile ilgili acil durumlar için hangarın uçak kapasitesine uygun sayıda ve vücut duşu çalışılan alana yakın mesafede bulunmaktadır ve bakımlıdır."]},{"title":"ELEKTRİK","subHeader":"","items":["Kullanılan tüm prizler topraklıdır.","Hasarlı fiş ve prizler bulunmamaktadır.","Prizler kapaklıdır ve akım kapasiteleri etiketlenmiştir.","Elektrik hattı korunaklı ve bakımlıdır.","Taşınabilir elektrik kabloları yalıtkan malzeme ile kaplanmıştır ve hasarsızdır.","Topraklama hattı korunaklı ve bakımlıdır. Ölçümleri yapılmaktadır.","Sahada bulunan iş ekipmanlarıtopraklanmaktadır.","Makine ve iş ekipmanlarının topraklaması bulunmaktadır.","Yükseltilebilen seyyar iş platformlarında topraklama bulunmaktadır ve bakımlıdır.","Elektrik panoları kapalı konumdadır.","Elektrik panolarına yetkisiz kişilerin erişimi engellenmiştir.","Elektrik panolarının önünde ulaşılmasını engelleyecek malzeme bulunmamaktadır.","Elektrik panolarının önünde yalıtkan paspas bulunmaktadır.","Elektrik panolarında kaçak akım rölesi mevcuttur ve periyodik kontrolleri yapılmaktadır.","Üretim alanında herhangi bir çalışma alanında kullanılan suni aydınlatma lambalarının kafes muhafazaları bulunmaktadır ve hasarsızdır.","Çalışanlar elektrikle çalışmaların riskleri konusunda bilgilendirilmiştir."]},{"title":"YANGIN VE PATLAMA","subHeader":"","items":["Boya, yapıştırıcı ve çözücü gibi yanıcı ve oksitleyici kimyasallar kullanılmamaktadır.","Kolayca tutuşabilir ve parlayabilir tehlikeli kimyasallar birbirlerinden ayrı depolanmaktadır.","Oksitleyici ve alevlenebilir maddelerin bulunduğu odalarda yeterli havalandırma sistemi bulunmaktadır.","Kimyasalların bulunduğu ortamlarda aydınlatma ve havalandırma tertibatı alev sızdırmaz (exproof) özelliktedir.","Ateşleyici kaynaklar (açık alev, elektrik ekipmanı, elektrostatik yükler ya da yüksek sıcaklık) bulunmamaktadır.","Elektrikli ekipman, statik elektrik gibi ateşleme kaynakları ile patlayıcı kimyasallar aynı yerde bulundurulmamaktadır.","Yangın söndürücüler kolay ulaşılabilirdir ve önünde ulaşılmasını engelleyecek malzemeler bulunmamaktadır.","Yangın söndürücüler yeterli sayıdadır, çalışır durumdadır ve periyodik kontrolleri yapılmaktadır.","Yangın ve patlama tehlikesinin erken fark edilmesini sağlayacak yangın ve gaz dedektörleri gibi algılama sistemleri bulunmaktadır ve çalışır durumdadır.","Yangın alarm düğmeleri çalışır durumdadır ve kolaylıkla ulaşılabilecek yerlerdedir.","Güç üniteleri uçağın yakıt deposuna belirlenen mesafede konumlandırılmaktadır.","Basınçlı hava hortumları gerilmelere karşı duvara sabitlenmiştir ve bağlantı elemanları kontrol edilmektedir.","Hava regülatörünün periyodik bakımları ve kontrolleri yapılmaktadır.","Nitrojen tüpleri korunaklı ayrı bir alanda, etiketli, valf başlığı bağlı, başlıkları muhafazalı şekilde depolanmaktadır.","Nitrojen tüpleri dolu ve boş olarak etiketlenmektedir ve ayrı ayrı yerlerde hangar dışında depolanmaktadır.","Hangarda bakıma girmeden önce uçakta bulunan yakıt tankları boşaltılmaktadır.","Yakıt tankında çalışmalarda yanıcı buhar konsantrasyonu ve oksijen miktarı ölçülerek kontrol altında tutulmaktadır.","Yangın söndürme ekipmanları ve bulunduğu yerler Sağlık ve Güvenlik İşaretleri Yönetmeliğine uygun şekilde işaretlenmiştir.","Acil çıkış kapıları hangar kapasitesine uygun sayıdadır.","Acil çıkış kapıları hangarın genelinden görülebilecek işaretlerle belirtilmiştir.","Acil çıkış yolları ve kapıları doğrudan dışarıya veya güvenli bir alana açılmaktadır ve çıkışı önleyecek hiçbir engel bulunmamaktadır.","Yangın ve patlama konularında mücadelede çalışanlara eğitimler verilmektedir ve tatbikatlar yaptırılmaktadır."]},{"title":"ERGONOMİ","subHeader":"","items":["Çalışanlar fiziksel yapılarına uygun işlerde görevlendirilmektedir.","İşin özelliği tekrarlı ve benzer hareketler yapmayı gerektirmemektedir.","Eğilerek, bükülerek, omuz hizasının üzerindeki bir noktaya uzanarak, çömelerek diz üstü ve sırt üstü çalışma gibi kas-iskelet sistemini zorlayan pozisyonlarda çalışılmamaktadır.","Dar, alçak ve sınırlandırılmış alanlarda biçimsiz duruş gerektiren pozisyonlarda çalışılmamaktadır.","İşe uygun araç, gereç ve ekipman belirlenmektedir.","Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engellenmekted","Çalışanlar yüklerin elle taşınmasından doğabilecek kas-iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda bilgilendirilmişt","Doğal duruşta çalışmanın sağlanması için çalışma tezgahlarının yüksekliği ayarlanabilirdir.","Çalışma alanları ayarlanabilir ve düzenlenebilirdir.","Dar, alçak ve sınırlandırılmış alanlarda çalışmalarda baş yaralanmalarını önleme için uygun baş koruyucunun kullanımı sağlanmaktadır.","Kapalı alanlarda çalışmalarda giriş ve çıkış, yaralanma riskini azaltacak şekilde yapılmaktadır.","Yakıt tankında çalışmalarda mutlaka dışarıda bir gözlemci bulunmaktadır.","Çalışanların kas-iskelet sistemi maruziyetlerinin azaltılması amacıyla molalar yeterli sıklıkta verilmektedir.","Dinlenme alanı çalışma sahasından ayrı bir yerdedir ve yeterlidir."]},{"title":"GENEL","subHeader":"","items":["Üretim alanında içerisinde tüm çalışma alanları temiz ve düzenlidir.","Üretim alanında sigara içilmesine izin verilmemektedir.","Üretim alanında termal konfor şartları (sıcaklık, nem, basınç vb.)düzenli olarak kontrol edilmektedir.","Gürültü seviyesi, aydınlatma düzeyi, sıcaklık, toza maruziyet ölçümleri yapılmıştır.","Hurda ve atık sahası bulunmaktadır.","Rotasyonlu çalışma sağlanmaktadır.","Alınan kararlarda çalışanların katılımı sağlanmaktadır.","Çalışanlar işin özelliği gereği maruz kaldıkları tehlike ve riskler konularında bilgilendirilmektedirler.","İlkyardım ve düzenli sağlık gözetimi sağlanmaktadır.","İlk yardım dolapları mevcuttur ve ilk yardım için eğitilmiş görevli çalışanlar bulunmaktadır.","Acil eylem planı mevcuttur.","Acil durumda gerekli olabilecek telefon numaraları herhangi bir acil durum anında kolaylıkla bulunabilecek yere asılmıştır.","Yapılan işin özelliğine uygun sağlık ve güvenlik işaretleri ile çalışanlar uyarılmıştır.","Kullanılan alet, teçhizatlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımların bakımı ve uygun muhafazası sağlanmaktadır.","Gerekli çalışmalarda işin özelliğine uygun kişisel koruyucu donanımların kullanılması sağlanmaktadır.","Çalışanların işe giriş muayeneleri ve periyodik kontrolleri yaptırılmaktadır.","İş kazaları ve meslek hastalıkları kayıt altına alınmaktadır ve yasal süresi içerisinde SGK’ ya bildirilmektedir.","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınmaktadır ve tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşılmaması için gerekli önlemler alınmaktadır.","Çalışanların iş sağlığı ve güvenliği temel eğitimini almaları sağlanmaktadır.","Çalışanlara görev ve sorumluluklarını güvenli şekilde yerine getirmeleri için yeterli süre sağlanmaktadır.","Çalışanlar yaptıkları işin özelliğine uygun gerekli eğitim ve bilgiye sahiptirler.","Çalışanlara görev ve sorumlulukları dışında talimat verilmemektedir.","Çalışanlar yetki, sorumluluk ve hedeflerini tam olarak bilmektedirler."]}]},{"templateId":"isg_yuk_yolcu_tasima_kontrol","title":"KARA YOLU İLE YAPILAN YÜK VE SERVİS TAŞIMACILIĞI İŞLERİ İÇİN KONTROL LİSTESİ","runningHeader":"KARA YOLU İLE YAPILAN YÜK VE SERVİS TAŞIMACILIĞI İŞLERİ İÇİN KONTROL LİSTESİ","shortName":"Yük ve Servis Taşımacılığı Kontrol Listesi (52 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"TAŞ-01","dosyaNo":"İSG-KL-05","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"GENEL","subHeader":"","items":["Araç iç zemini, kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplanmış mıdır?","Zemin düzenli olarak kontrol ediliyor mu?","Araçlar düzenli olarak havalandırılıyor mu?","Araçlarda bulunan iklimlendirme cihazlarının kontrolleri düzenli aralıklarla yapılıyor mu?","Araçlardaki cam yüzeylerde kırık veya çatlak bulunuyor mu?","Araçlar içerisinde monte edilmiş raflar, TV üniteleri veya üst bölmelere konulan yüklerin/ malzemelerin düşmesini önleyecek tedbirler alınıyor mu?","Araç içerisinde sigara içilmesi yasak mı? Çalışanlar bu konuda bilgilendiriliyor mu?","Araç içi aydınlatmalar çalışır halde bulunuyor mu?","Çalışanların egzoz gazına ve toza maruziyetini önlenmek için gerekli önlemler alınıyor mu?","Aşırı sıcak veya soğuk hava koşullarında araçlarda uygun termal konfor şartları sağlanıyor mu?","Araçlar kullanımdan sonra temizlenmekte, çöpler düzenli olarak ve uygun şekilde toplanıyor mu?","Tüm araçların elektrik aksamları (göstergeler, farlar, sigortalar vb.) düzenli aralıklarla kontrol ediliyor mu?","Araçların servis ve bakımları periyodik olarak yapılıyor mu?","Araç içine alınmasına izin verilen yükler koridorlara yerleştiriliyor mu?","Yükler, acil çıkış yollarını veya kapıları kapatıyor mu?","Sürücülerin veya muavinlerin özellikle dönüşümlü çalışmaları sırasında barınma gibi temel ihtiyaçları için uygun alanlar ayrılıyor mu?"]},{"title":"ACİL DURUMLAR","subHeader":"","items":["Araçlarda yangın söndürücüler mevcut mu?","Yangın söndürücülerin son kullanma tarihleri ve basınçları kontrol ediliyor mu?","Araç içerisinde kullanılan cihazların devrilme ihtimaline karşı gerekli tedbirler alınıyor mu?","Elektrikli cihazlar yanıcı malzemelerle temas etmeyecek şekilde yerleştiriliyor mu?","Yolcuların yanıcı, patlayıcı, parlayıcı vb. kaza anında tehlike teşkil edebilecek kimyasal içerikli yükleri araç içerisine alınıyor mu?","Acil durumlar ile ilgili iletişime geçilecek telefon numaraları (ambulans, polis vb.) araç içerisinde bulunduruluyor mu?","Lipit Petrol Gazı (LPG) ile çalışan araçların LPG tanklarının kontrolleri düzenli olarak yapılıyor mu?","Araçlarda, içerisinde yeterli malzeme bulunan ilkyardım çantası bulunuyor mu?"]},{"title":"ÇALIŞMA ORTAMI (SEYİR HALİNDE GÜVENLİK)","subHeader":"","items":["Çalışanların, sürüş sırasında titreşime maruz kalmamaları için araçların bakımları düzenli olarak yapılıyor mu?","Çalışanlara, trafik kurallarına ve levhalarına uymaları konusunda gerekli talimatlar veriliyor mu?","Araçların güvenlik donanımları çalışır durumda mıdır?","Çalışanlara, hava koşulları ve karayollarının durumu hakkında düzenli bilgi akışı sağlanıyor mu?","Araçlarda mevsim koşullarına uygun lastik kullanılıyor mu?","Çalışanlara, sürüş sırasında emniyet kemerlerinin takılması konusunda talimat veriliyor mu?","Yolcuların araç sürücüsü ile gereksiz konuşmaları engelleniyor mu?","Konteyner bağlantıları ve kapaklarının kilitli olması, dorse bağlantısı kontrol ediliyormu?"]},{"title":"PSİKOSOSYAL ETKENLER","subHeader":"","items":["Çalışanlar, maruz kalabilecekleri olumsuz davranışlar (tehdit, hakaret vb.) karşısında nasıl davranacağını biliyor mu?","Çalışanlar yaptıkları işten kaynaklanan stres ile baş edebilmeleri için gerekli eğitimi alıyor mu?","Çalışanların çalışma programları belirleniyor mu?","Çalışanlara, hareket saatlerine uyma konusunda talimat veriliyor mu?","Vardiyalı çalışma düzeninin çalışanlar üzerinde oluşturduğu olumsuz psikososyal etkiler vardiyalar en makul şekilde düzenlenerek asgari düzeye indiriliyor mu?"]},{"title":"ERGONOMİ","subHeader":"","items":["Çalışanlar, uzun süre aynı pozisyonda veya fiziksel anlamda zorlayıcı hareket yapmamaları konusunda bilgilendiriliyor mu?","Tüm araçlarda, ayarlanabilir sürücü koltukları mevcut mu?"]},{"title":"ELLE TAŞIMA","subHeader":"","items":["Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engelleniyor mu?","Yüklerin elle taşınmasının da neden olabileceği kas iskelet sistemi hastalıklarına karşı çalışanlar bilgilendiriliyor mu?","Çalışanlar, elle kaldırma/taşıma (yolcu bagajına yardım gibi) yaptıkları durumda kendi sağlıklarını tehlikeye atmayacak şekilde hareket ediyor mu?"]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş muayenesi yaptırılıyor mu?","Çalışanların periyodik muayeneleri zamanında yaptırılıyor mu?","Çalışanların karşı karşıya kaldıkları kazalar ve işe bağlı oluşan hastalıklar Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Çalışanların karşı karşıya kaldıkları önceden olmuş kazalar veya işe bağlı hastalıklar incelenerek yeniden meydana gelmeleri önleniyor mu?","Çalışanların, gece vardiyası veya değişik vardiya çalışmalarına uyumlarındaki sorunlar izleniyor mu?","Gece vardiyasında veya değişik vardiya çalışmaları olan çalışanlar düzenli sağlık gözetiminden geçiriliyor mu?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Çalışanlara genel iş sağlığı ve güvenliği eğitimi veriliyor mu?","Çalışanlar, yaptıkları iş konusunda eğitiliyor mu veya yönlendiriliyor mu?","Eğitim ve bilgilendirme ile ilgili belgeler kayıt altına alınıyor mu?","Eğitim ve bilgilendirme kayıtları uygun şekilde muhafaza ediliyor mu?"]}]},{"templateId":"isg_degirmen_un_irmik_kontrol","title":"TEKİNAK UN İRMİK İMALATI İÇİN KONTROL LİSTESİ","runningHeader":"TEKİNAK UN İRMİK İMALATI İÇİN KONTROL LİSTESİ","shortName":"Değirmen (Un İrmik İmalatı) Kontrol Listesi (118 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"DĞR-01","dosyaNo":"İSG-KL-06","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"GENEL & İŞYERİ DÜZENİ VE HİJYEN","subHeader":"","items":["Zemin, kayma veya düşmeyi önleyecek şekilde tasarlanmış ve iç ve dış zeminler (işyeri girişi, merdivenler vs.) düzenli olarak kontrol ediliyor mu?","Çalışma alanlarında dökülen malzemeler veya diğer sebeplerden ötürü kayganlaşmış zeminler ya da geçitler derhal temizleniyor mu?","Zeminde eşik veya benzeri seviye değişiklikleri varsa bunlar için düzeltici işlemler yapılıyor mu?","Çalışma alanında yerlerde, nesnelerin/cisimlerin bırakılması nedeniyle engeller oluşması önleniyor mu?","Zeminde çökme, erime vb. deformasyonlar bulunması halinde bunlara yönelik düzeltici çalışmalar yapılıyor mu?","Aynalar da dâhil cam yüzeyler (cam aksamlı mobilyalar, kapı, pencere vb.) uygun şekilde monte edilmiş ve yüzeyler üzerinde kırık ve çatlak gibi hatalar bulunması durumunda yenileri ile değiştiriliyor mu?","Bütün alanlar iyi aydınlatılmış, pencere alanı yeterince büyük ve doğal aydınlatmadan yeterinc faydalanılıyor mu?","Açık alev, elektrikli ekipman, elektrostatik yük veya yüksek sıcaklık gibi tutuşturucu kaynaklar çalışma ortamından uzaklaştırılmış mı?","Çalışma alanında temiz hava akımı bulunuyor ve tüm alanlar düzenli olarak havalandırılıyor mu?","Tüm alanlardaki mevcut iklimlendirme cihazlarının kontrolleri düzenli aralıklarla yaptırılıyor mu?","Çalışma ortamı sıcaklığının çok soğuk ya da çok sıcak olması engelleniyor mu?","İşyeri içerisindeki sıcaklık ve nem, rahatsızlık vermeyecek düzeyde tutuluyor mu?","İnsanlardan, makine veya donanımlardan kaynaklanabilecek veya dış ortam kaynaklı gürültünün rahatsız edici düzeyde olması engelleniyor mu?","Makine veya donanımlardan kaynaklanabilecek titreşimin rahatsız edici düzeyde olması engelleniyor mu?","Çalışanların yeme-içme, barınma gibi temel ihtiyaçları için uygun donanımlı alanlar ayrılmış mı?","İşyerinin temizliği düzenli olarak yapılıyor ve çalışma ortamında, hijyen açısından gerekli şartlar sağlanıyor mu?","Temizlik yapılan alanda kaymayı önlemek için gerekli önlemler alınıyor mu?","Tozun yere çökmesi nedeniyle kaygan hale gelen yerler düzenli olarak temizleniyor mu?","Toz veya malzeme artıklarının yerlerde veya taban kenarlarında birikmesi önleniyor mu?","Çalışanlar, işlerini bitirdikten sonra bütün malzemeleri yerlerine düzenli olarak yerleştiriyor mu?","Çalışma alanı çalışanların rahat çalışmasını sağlayacak genişlikte ve çalışma ortamı çalışanların faaliyetlerini kısıtlamayacak şekilde tasarlanmış mı?","Çöpler ve atıklar düzenli olarak ve uygun şekilde toplanıyor mu?","Çöp kutuları, her boşaltmadan sonra dezenfekte ediliyor mu?","İşyeri içerisindeki çalışma alanlarında sigara içilmesi yasaklanmış ve çalışanlar bu konuda bilgilendirilmiş mi?","İçinde yeterli malzemenin bulunduğu ilk yardım dolabı mevcut mu?","Düzenli olarak haşere kontrolü yapılıyor mu?","Atık su arıtma sistemi mevcut mudur veya ortaya çıkan atık su çevreye zarar vermeyecek şekilde uzaklaştırılıyor mu?"]},{"title":"MAKİNELER, EL ALETLERİ VE YARDIMCI APARATLAR","subHeader":"","items":["Makina, araç ve gereç tedariğinde CE işaretli olanların alınması sağlanıyor mu?","Kesici veya delici nitelikteki alet veya ekipmanların açıkta bulundurulması engelleniyor ve koruyucu içerisinde muhafaza edilmesi sağlanıyor mu?","Kesici veya delici alet veya ekipmanlar uygun aralıklarla, kullanım öncesi ve sonrasında kontrol ediliyor mu?","Tüm alet veya ekipmanların tasarım amaçlarına uygun yönde kullanılması sağlanıyor mu?","Bütün makinalarda gerekli uyarı işaretleri bulunuyor mu?","Bütün makinaların etrafında çalışma için yeterli alan mevcut mu?","Tüm alet ve gereçlerin kullanımında gerekli hijyen şartları sağlanıyor mu?","Kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde kullanılıyor mu?","Makineler için üretici firmadan, Türkçe kullanım kılavuzları temin edilmiş ve makineler bu kılavuza uygun olarak kullanılıyor mu?","Özellikle hareketli parçaları olan makineler/aletler üreticisinin talimatları doğrultusunda koruma panelleri vb. önlemler ile koruma altına alınmış mı?","İçerisinde ve parçalarında dönen aksamları bulunan elektrikli aletler ile yapılan çalışmalar sırasında gerekli önlemler alınıyor mu?","Makinaların kazara/istemeden çalıştırılması engelleniyor ve makinaların acil durdurma mekanizmaları bulunuyor mu?","İşveren makine koruyucularının çalışanlar tarafından uygun olarak kullanıp kullanılmadığını kontrol ediyor mu?","Makine ve iş ekipmanlarının üzerinde bulunan aci durdurma butonları ulaşılabilir ve çalışır durumda mı?","Makine ve iş ekipmanlarının koruyucuları ek risk oluşturmayacak şekilde tasarlanmış mı?","Makine ve iş ekipmanlarının koruyucusu devre dış kaldığında makine/ekipmanın çalıştırılması engelleniyor mu?","İmalatçının talimatları doğrultusunda tüm makinelerin günlük bakımları ve periyodik kontrolleri yapılıyor mu?","Özel cihaz, el aletleri ya da teknik aparatların sadece özel eğitim almış çalışanlar tarafından ve gerekli önlemler alınarak kullanılması sağlanıyor mu?"]},{"title":"ELEKTRİK","subHeader":"","items":["Elektrik/sigorta kutuları kilitlenmiş, yetkisiz kişilerin erişimleri önlenmiş mi?","Tüm prizlere topraklama yapılmış mı?","Kaçak akım rölesi ana elektrik hattına bağlanmış mı?","Kaçak akım rölelerinin kontrol ve bakımları düzen olarak yapılıyor mu?","Tüm sigortaların korunaklı yerlerde olması sağlanmış mı?","Kabloların ekleme yapılarak (kesilip bantlanarak vb.)uzatılması engelleniyor mu?","Açık uçlu, hasarlı, yıpranmış elektrik kablolarının kullanılması engelleniyor mu?","Elektrikle ilgili bağlantılar sürekli kontrol ediliyor mu?","Acil durumlarda elektrik enerjisi kolayca kesilebilmekte mi?","Üretim kaynaklı toz ve kirliliğin elektrik panoları v tesisat üzerinde birikmesi engelleniyor mu?","Aynı uzatma kablosu ile birden fazla makine ve ekipman çalıştırılması engelleniyor mu?","Yanıcı gazların bulunduğu ortamlarda yer alan elektrik panoları ve cihazlara uygun yalıtım yapılmış mı?","Elektrik kontrol panosuna ulaşımı engelleyecek malzemeler ortadan kaldırılmış mı?","Kontrol panosunun önündeki alanın zeminine uygun yalıtım yapılmış mı?","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmesi engelleniyor mu?"]},{"title":"ERGONOMİ","subHeader":"","items":["Çalışanların kas-iskelet sistemlerini zorlayan pozisyonlarda çalışması engelleniyor mu?","Çalışanların uzun süre oturarak, ayakta veya tekrarlayan iş yapması engelleniyor mu?","Çalışanların, işlerini yaparken çok uzak mesafelere uzanmak zorunda kalmaları engelleniyor mu?","Çalışanlara uygun ve kaymaz ayakkabılar sağlanmış mı?","Çalışanlara, yaptıkları işe uygun masa, sandalye veya destek ekipman sağlanmış mı?","Çalışanlar, çalışma alanlarını kendilerine göre ayarlama ve düzenleme imkânları var mı?"]},{"title":"ELLE TAŞIMA","subHeader":"","items":["Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engelleniyor mu?","Yüklerin uygunsuz taşınmasını gerektiren durumlar ortadan kaldırılmış mı?","Yüklerin elle taşınmasından doğabilecek kas iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda çalışanlar bilgilendiriliyor mu?","Sırt ve bel incinmesi riski oluşturabilecek yüklerin itilmesini ya da çekilmesini sağlayacak uygun taşıma araçları sağlanıyor mu?"]},{"title":"YÜKLERİN TAŞINMASI","subHeader":"","items":["El arabası ve transpalet gibi yüklerin taşınmasında kullanılan ekipmanların bakımları düzenli yapılıyo mu?","Yüklerin taşınmasında kullanılan ekipmanları itmek veya çekmek için fazlaca güç kullanılması engelleniyor mu?","Zeminin veya dar alanların; yüklerin taşınmasını, itilmesini veya çekilmesini zorlaştıracak şekilde eğimli/dar olması engellenmiş mi?"]},{"title":"KİMYASALLAR","subHeader":"","items":["Tehlikeli kimyasallar yerine tehlikeli olmayan veya daha az tehlikeli olanların kullanılması sağlanıyor mu?","Çalışanlar işyerinde kullanılan kimyasalların tehlikeleri hakkında bilgilendirilmiş mi?","Tehlikeli kimyasalların kayıtları tutulmakta mı?","Tehlikeli kimyasalların kullanma talimatları mevcu mu?","Tehlikeli kimyasalların kayıtlarında içerik listesi ve güncel Malzeme Güvenlik Bilgi Formları (MGBF) yer almakta mı?","Çalışanlar, kullanma kılavuzu bulunmayan ya da kullanma talimatı henüz hazırlanmamış tehlikeli kimyasalları kullanmamaları konusunda talimatlandırılmış mı?","Kimyasal maddelerin kullanım amaçları dışında kullanılması engelleniyor mu?","Gaz veya toz gibi zarar verici emisyona sebep olabilecek kimyasal maddelerin açıkta bulunduğu işlemin yapıldığı yerde zararlı emisyona maruz kalmamak için vakum özelliği olan davlumbaz tesisatı veya benzeri bir sistem kurulmuş mu?","Kimyasalların üzerinde uygulama yöntemi, kullanılacak koruyucu ekipman ve zararlarını gösteren etiketler mevcut mu?","Kimyasal maddelerin (özellikle içerikleri nedeniyle alevlenebilir olanların) saklama koşullarına uyuluyor, bu malzemeler ısı, ışık ve diğer malzemelerden uzakta muhafaza edilmesi sağlanıyor mu?","Birbirleri ile tepkimeye girerek tehlikeli salımlar oluşturabilecek kimyasal maddelerin ayrı yerlerde muhafaza edilmesi sağlanıyor mu?","Kimyasalların kullanıldığı ve bulunduğu alanlarda yeterli havalandırma sağlanıyor mu?","Kimyasalların kullanımı sırasında alerji ve tahrişler önlemek için cilt, göz veya solunum teması engelleniyor mu?","Çalışmalar sırasında parlayıcı ve yanıcı maddelerin kullanılması engelleniyor veya kullanımın zorunlu olduğu yerlerde çalışanların sağlık ve güvenliğine ilişkin önlemler alınıyor mu?","Süreçlerde, hidrojen ve metan; benzen buharı ve aseton gibi patlayıcı karışımlar veya parlayıcı madde ortaya çıkması engelleniyor mu?","İşletme içinde sıcak çalışma (kaynak vb.) yapılmas durumunda çalışanların sağlık ve güvenliğine ilişkin önlemler alınıyor mu?","Yakıcı veya aşındırıcı maddeler veya yanıcı gazlarla yapılan çalışmalarda gerekli önlemler alınıyor mu?","Kimyasal madde üzerindeki malzeme güvenlik bilg formu kaybolacak şekilde, kimyasal maddelerin başka bir kap/kutu/şişelere aktarılması engelleniyor ve maddelerin orijinal kutuları içerisinde tutulması sağlanıyor mu?"]},{"title":"ACİL DURUMLAR","subHeader":"","items":["İşyerinde, acil durum planı hazırlanmış mı?","Yeterli sayıda yangın söndürücü mevcut ve son kullanma tarihleri ve basınçları kontrol ediliyor mu?","Yangın merdivenine açılan acil çıkış kapıları kilitli olmayıp dışa doğru açılacak şekilde tasarlanmış mı?","Acil çıkış kapılarına ulaşımı engelleyecek faktörler ortadan kaldırılmış ve yangın merdivenlerinin amacı dışında kullanılması engelleniyor mu?","Acil duruma neden olan olaya ilişkin iletişime geçilecek (yangın, gaz kaçağı, deprem vb.) telefon numaraları görünür yer(ler)e asılmış mı?","Yangın uyarı sisteminin (sesli ve ışıklı uyarı) çalışır durumda olması sağlanıyor mu?","Kapı ve kaçış yollarını gösteren acil durum levhaları uygun yerlere yerleştirilmiş ve yangın merdiveninde ışıklandırma sağlanmış mı?","Çalışanlar, acil durumlarda ne yapması gerektiği konusunda bilgilendirilmiş mi?"]},{"title":"DEPOLAMA","subHeader":"","items":["Yanıcı ve oksitleyici maddelerin havalandırması bulunmayan odalarda depolanması engellenmiş mi?","Atıkların gerektiğinde uygun işlemlerden geçirildikten sonra çalışanlar tarafından güvenli bi biçimde toplanması, depolanması ve işyerinden uzaklaştırılması, güvenli ve özel kapların kullanılması da dâhil uygun yöntemlerle yapılması sağlanıyor mu?","Tehlikeli maddelerin yüksek sıcaklıkta depolanması engelleniyor mu?"]},{"title":"PSİKOSOSYAL ETKENLER","subHeader":"","items":["Çalışanlar ile işveren(ler) arasında iyi bir iletişim sürdürülüyor mu?","Çalışanlar; yetki, sorumluluk ve çalışma hedeflerin net olarak biliyor mu?","Çalışanlara, görev ve sorumlulukları haricinde talimat verilmesi engelleniyor mu?"]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş ve periyodik kontrolleri yaptırılıyor mu?","İş kazaları ve meslek hastalıkları vakaları Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınıyor, tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşmamak için gerekli önlemler alınıyor mu?","Çalışanların sıcak yüzeyle ya da püsküren buharla temas edip yanması gibi tehlikelere karşı önlemle alınıyor mu?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Tüm çalışanlara enfeksiyon riskini azaltmak için genel hijyen bilgisi verilmiş ve gerekli önlemler alınmış mı?","Çalışanlar iş sağlığı ve güvenliği konusunda eğitim almışlar mı?","Çalışanlar yaptıkları işle ilgili olarak gerekli eğitim ve bilgiye sahip mi?","Çalışanlar biyolojik etkenlerle çalışma sırasında maruz kalabileceği riskler konusunda bilgilendiriliyor mu?","Çalışanlar tehlikeli kimyasallarla çalışma sırasında maruz kalınabilecek riskler ve kimyasallar ile güvenli çalışma konusunda bilgilendiriliyor mu?","Çalışanlar kesilme, batma, yanma vb. nedenler ile oluşan yaralara hangi durumda ve kim tarafından müdahale edileceği konusunda bilgilendiriliyor mu?","Çalışanlar kullandıkları makine, araç ve gereçlerin güvenli kullanımı konusunda eğitiliyor mu?","Çalışanlar sağlık ve güvenlik işaretlerinin anlamlar konusunda eğitilmiş mi?","Eğitim ve bilgilendirme ile ilgili belgeler kayıt altın alınıyor ve kayıtlar uygun şekilde muhafaza ediliyor mu?"]}]},{"templateId":"isg_kargo_transfer_kontrol","title":"KARGO TRANSFER MERKEZLERİ İÇİN KONTROL LİSTESİ","runningHeader":"KARGO TRANSFER MERKEZLERİ İÇİN KONTROL LİSTESİ","shortName":"Kargo Transfer Merkezleri Kontrol Listesi (154 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"KRG-01","dosyaNo":"İSG-KL-07","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"","sections":[{"title":"GENEL & İŞYERİ DÜZENİ VE HİJYEN","subHeader":"","items":["Transfer merkezi yerleşimi, yapılan işe uygun olarak ve çalışanların faaliyetlerini kısıtlamayacak şekilde tasarlanmış mı?","Zemin hasar görmüş mü ve zeminde çökme, erime vb. deformasyonlar bulunuyor mu?","Kayma-takılma-düşmeye neden olabilecek herhangi bir etmen veya gelişi güzel yerleştirilmiş kargolar var mı?","Zemin kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplanmış mı ve iç zeminler düzenli olarak kontrol ediliyor mu?","Zeminde sıvı döküntü(su, yağ, kimyasal vb.) veya kargo kutularından kaynaklı sızıntı var mı?","Merdiven genişlikleri, basamak yükseklikleri ve tırabzanlar uygun mu?","Merdivenler ve rampalar korkuluklarla ve kaydırmazlarla donatılmış mı?","Çalışma alanı, zemin, yollar, tezgâhlar, mahfazalar, raflar ve askılar düzenli ve temiz mi?","İşyerinin temizliği düzenli olarak yapılıyor ve çalışma ortamında, hijyen açısından gerekli şartlar sağlanıyor mu?","Çalışma alanında temizlik yapılan yerlerde kaymayı önlemek için gerekli önlemler alınıyor mu?","Transfer alanı içerisindeki tehlikelere karşı uyarı işaretleri bulunmakta mı?","Uygun yerlerde yeterli sayıda ve büyüklükte atık kutuları bulunmakta mı?","Atık konteynerleri hasar görmemiş, düzgün ve içeriğine uygun şekilde işaretlenmiş mi?","Çalışma alanında artık, dökük, kullanılmayan ve çalışmaya engel olabilecek malzeme ya da kargo bırakılmış mı?","Çalışanlar, işlerini bitirdikten sonra bütün malzemeleri yerlerine düzenli olarak yerleştiriyor mu?","Çalışanların yeme-içme, temizlik, soyunma alanları temel ihtiyaçları için uygun donanımlı alanlar ayrılmış mı?","Elleri ve vücudu gerektiğinde yıkayabilecek temiz lavabo ve duşlar mevcut mu?","Çalışanlar için kolay ulaşılabilir noktalarda temiz içme suyu mevcut mu?","İşyeri içerisinde duvarlara monte edilmiş raflar, askılıklar ve benzeri diğer malzemeler çalışanların üzerine düşmeyecek şekilde sabitlenmiş mi?","Kullanılan ekipman ve makineler için ayrı bir depolama alanı var mı?","Yangın ve kazaları önlemek için transfer merkezinin etrafındaki çöp ve atıklar düzenli olarak uzaklaştırılıyor mu?","Transfer alanı çatısının dayanımı ve özellikleri; ısı- rüzgâr-yağmur ve kara dayanıklı mı?","Çalışma ortamında aşırı sıcak ya da soğuk ortamlarda çalışma yapılmaması sağlanıyor mu?","Çalışma alanında temiz hava akımı bulunuyor ve tüm alanlar düzenli olarak havalandırılıyor mu?","İşyeri çalışma ortamında sürekli açık tutulan araç giriş-çıkış kapılarından kaynaklı iklimsel koşullar (aşırı sıcak, nem, basınç, düşük sıcaklık, zararlı cereyan, vb.) çalışanlara rahatsızlık vermeyecek düzeyde tutuluyor mu?","Açık yükleme alanında çalışanlarda güneş ışığından kaynaklı radyasyona ya da aşırı soğuğa maruziyetin önüne geçilmiş mi?","Suni aydınlatmalar ve lambalar zarar görmemiş, temiz ve çalışır halde bulunuyor mu? (Lambaların kontrolleri yapılıyor mu?)","Gece vardiyasında çalışanlar için de gündüz çalışmasına eşit ve homojen şekilde yeterli suni aydınlatma sağlanmış mı?","Bütün alanlar iyi aydınlatılmış ve doğal aydınlatmadan yeterince faydalanılıyor mu?","Transfer araçlarından, makine veya donanımlardan kaynaklanabilecek titreşimin rahatsız edici düzeyde olması engelleniyor mu?","Çalışma ortamında toz maruziyetinin (organik, inorganik) önüne geçilmekte mi?","İnsanlardan, transfer araçlarından, makine veya donanımlardan kaynaklanabilecek veya dış ortam kaynaklı gürültünün rahatsız edici düzeyde olması engelleniyor mu?"]},{"title":"MAKİNELER, EL ALETLERİ VE YARDIMCI EKİPMANLAR","subHeader":"","items":["Makine, araç ve gereç tedariğinde CE işaretli olanların alınması sağlanıyor mu?","Tüm makine, konveyör ve ekipmanlar uygun aralıklarla, kullanım öncesi ve sonrasında kontrol ediliyor mu; bozuk veya arızalı ekipmanların kullanımı engelleniyor mu?","Tüm makine, konveyör, alet veya ekipmanların tasarım amaçlarına uygun yönde kullanılması sağlanıyor mu?","Bütün makinelerin ve konveyörlerin etrafında çalışma için yeterli alan mevcut mu?","Tüm alet ve gereçlerin kullanımında gerekli hijyen şartları sağlanıyor mu?","Kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde kullanılıyor mu?","Makineler için üretici firmadan, Türkçe kullanım kılavuzları temin edilmiş mi ve makineler bu kılavuza uygun olarak kullanılıyor mu?","Makine ve iş ekipmanları kullanılırken koruyucularının her zaman yerinde ve iyi durumda olması sağlanıyor mu?","İçerisinde ve parçalarında dönen aksamları bulunan elektrikli aletler ile yapılan çalışmalar sırasında gerekli önlemler alınıyor mu?","Makinelerin kazara/istemeden çalıştırılması engelleniyor ve makinelerin acil durdurma düğmeleri bulunuyor mu?","İşveren makine koruyucularının çalışanlar tarafından uygun olarak kullanıp kullanılmadığını kontrol ediyor mu?","İmalatçının talimatları doğrultusunda tüm makine ve ekipmanların düzenli bakım ve periyodik kontrolleri yapılıyor mu?","Bakım onarım işleri yetkin ve yetkili kişiler tarafından gerçekleştiriliyor mu?","Özel cihaz, el aletleri ya da teknik aparatların sadece özel eğitim almış çalışanlar tarafından ve gerekli önlemler alınarak kullanılması sağlanıyor mu?"]},{"title":"ELEKTRİK","subHeader":"","items":["Elektrik/sigorta kutuları kilitlenmiş ve yetkisiz kişilerin erişimleri önlenmiş mi?","Elektrik panolarında gerekli güvenlik ve uyarı ikaz levhaları bulunuyor mu?","Elektrikle ilgili işler yetkili ve uzman kişilere yaptırılıyor mu?","Elektrik panolarının önünde engel var mı ve önündeki zemin yalıtım malzemesiyle kaplanmış mı?","Tüm sigortaların korunaklı yerlerde olması sağlanmış mı?","İşyerinde kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde kullanılıyor mu?","Kaçak akım rölesi ana elektrik hattına bağlanmış mı?","Elektrikle ilgili bağlantılar sürekli kontrol ediliyor mu?","Elektrik tesisatı ve kabloların bakımları düzenli olarak yapılıyor mu?","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmesi engelleniyor mu?"]},{"title":"ELLE TAŞIMA","subHeader":"","items":["Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engelleniyor mu?","Yüklerin elle taşınmasından doğabilecek kas iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda çalışanlar bilgilendiriliyor mu?","Sırt, omuz, el, bilek ve bel incinmesi riski oluşturabilecek yüklerin taşınması, itilmesini ya da çekilmesini sağlayacak uygun taşıma araçları sağlanıyor mu?","Taşıma araçlarının çalışanı zorlayacak şekilde aşırı yüklenmemesi sağlanıyor mu?","Ağırlık merkezi sabit olmayan yüklerin taşınması işlemi kontrollü olarak yapılıyor mu?"]},{"title":"ERGONOMİ","subHeader":"","items":["Çalışanların uzun süre aynı pozisyonda veya fiziksel anlamda zorlayıcı çalışmaları (ağır yük kaldırma dahil) engelleniyor mu?","Çalışma ortam ve şartları, çalışanların yükleri uygun bir vücut pozisyonunda taşımasına uygun mu?","Özellikle vücudun belden dönmesini gerektiren bedensel çalışmalar engelleniyor mu?","Fazlaca yukarıya uzanmayı veya aşağıya eğilmeyi gerektiren işlerde çalışanların uzun süre hareketsiz aynı pozisyonda kalması engelleniyor mu?","Çalışanlara yaptıkları işe, termal koşullara ve fizyolojik özelliklerine uygun iş kıyafetleri sağlanmış mı?","Çalışanlara, yaptıkları işe uygun ergonomik masa, sandalye veya destek ekipman sağlanmış mı?","Oturarak yapılan çalışmalarda oturma duruşu uygun mu?","Kullanılan ekipman çalışanın fizyolojik özelliklerine göre ayarlanabilir mi?","Kas iskelet sistemini zorlayıcı ve tekrarlayan hareketleri önleyici tedbirler alınmış mı?","Taşıma araçları ve paletler ergonomik mi?","Taşıma araçları ve paletlerin çalışanı zorlayacak şekilde aşırı yüklenmesi engelleniyor mu?","Ekranlı aracın parlaklığı ve ekranın yapısı çalışanı olumsuz etkiliyor mu?","Ekranlı araçlarla çalışma, çalışan sağlığı açısından uygun mu?"]},{"title":"KİMYASAL ve BİYOLOJİK ETMENLER","subHeader":"","items":["Kimyasal, biyolojik ya da zararlı madde taşıması yapılıyor mu?","Zararlı kimyasallar ile çalışılıyor ise güvenli çalışma yöntemleri mi uygulanıyor?","Biyolojik madde taşınması yapılıyor ise, biyolojik etkenlerin ortama yayılmasını önleyecek veya ortamda en az düzeyde bulunmasını sağlayacak düzenlemeler var mı?","Kimyasal maddelere yetkisiz kişilerin erişimi engellenmiş mi?","Kimyasalların kullanımı, saklanması ve taşınması konusunda gerekli güvenlik tedbirleri alınıyor mu?","Kimyasalların Güvenlik Bilgi Formları (SDS) mevcut mu?","Çalışanların kimyasallara/biyolojik maddelere doğrudan maruziyeti engellenmekte mi?","Kimyasalların üzerinde içeriği, uygulama yöntemi, kullanılacak koruyucu ekipman ve zararlarını gösteren etiketler mevcut mu?","Kimyasal/biyolojik madde maruziyetine karşı uygun KKD kullanılıyor mu?","Taşınan kargolarda içeriği bilinmeyen herhangi bir sıvı ya da toz sızıntısı oluyor mu?","Kimyasal/biyolojik atıklar ya da sızıntılar uygun şekilde imha ediliyor mu?","İçeriği bilinmeyen ve kimyasal/biyolojik madde içeren kargoların (özellikle içerikleri nedeniyle alevlenebilir olanların) saklama koşullarına uyuluyor, bu malzemeler ısı, ışık ve diğer malzemelerden uzakta muhafaza ediliyor ve taşınıyor mu?","Birbirleri ile tepkimeye girerek tehlikeli salımlar oluşturabilecek maddeleri içeren kargoların ayrı yerlerde muhafaza edilmesi ve taşınması sağlanıyor mu?","Taşınan kargolar içerdikleri kimyasallar/biyolojik maddelerden dolayı kuryeleri ya da transfer merkezi çalışanlarının sağlığını etkiliyor mu? (alerji, göz tahrişi, soluma, vb.)"]},{"title":"ACİL DURUMLAR","subHeader":"","items":["İşyerinde, acil durum planı hazırlanmış mı?","Yeterli sayıda yangın söndürücü mevcut ve son kullanma tarihleri ve basınçları kontrol ediliyor mu?","Yangın söndürme ekipmanına ulaşım kolay, önünde engel ya da malzeme yok ve ihtiyaç halinde kullanıma hazır durumda mı?","Yangın merdiveni kapıları ve acil çıkış kapıları kilitli olmayıp dışa doğru açılacak şekilde tasarlanmış mı?","Acil çıkış kapılarına ulaşımı engelleyecek faktörler ortadan kaldırılmış ve yangın merdivenlerinin amacı dışında kullanılması engelleniyor mu?","Acil duruma neden olan olaya ilişkin iletişime geçilecek telefon numaraları (itfaiye, ambulans, polis, vb.) görünür yer(ler)e asılmış mı?","Acil durumda iletişim telefonları çalışanlar tarafından biliniyor mu?","Yangın uyarı sisteminin (sesli ve ışıklı uyarı) çalışır durumda olması sağlanıyor mu?","Kapı ve kaçış yollarını gösteren acil durum levhaları uygun yerlere yerleştirilmiş ve yangın merdiveninde ışıklandırma sağlanmış mı?","İlkyardım dolabı mevcut mu ve içeriği uygun mu?"]},{"title":"PSİKOSOSYAL ETMENLER","subHeader":"","items":["Çalışanlar ile işveren(ler) arasında iyi bir iletişim sürdürülüyor mu?","Çalışanlar; yetki, sorumluluk ve çalışma hedeflerini net olarak biliyor mu?","Çalışanlara, görev ve sorumlulukları haricinde talimat verilmesi engelleniyor mu?","Çalışma zamanı ile ilgili çalışanlara baskı uygulanıyor mu?","Çalışanlar için uygun dinlenme alanları mevcut mu?"]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş muayeneleri ve periyodik kontrolleri yaptırılıyor mu?","İş kazaları ve meslek hastalıkları Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Daha önce meydana gelmiş kazalar ve ramak kala olaylar incelenerek kayıt altına alınıyor, tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşmamak için gerekli önlemler alınıyor mu?"]},{"title":"YÜKSEKTE ÇALIŞMA","subHeader":"","items":["Bütün taşınabilir merdivenler güvenli ve yapılan işler için uygun mu?","Merdivenler yüksekte kullanıldığında sağlam ve dengeli bir şekilde durması sağlanmakta mı?","Taşınabilir merdivenlerin periyodik bakımları ve kontrolleri düzenli olarak ve her kullanım öncesi yapılmakta mı?","Yüksekte çalışılan zeminler ve merdiven ayakları kaydırmaz tabanlı mı?","Yüksek bölümler sabit korkuluklar ve tırabzanlar ile çevrilmiş mi?","Yüksek istifleme yapılan bölümlerdeki yükler çalışanların üzerine düşmeyecek şekilde sabitlenmiş mi?"]},{"title":"NAKLİYAT VE HAREKET EDEN ARAÇLAR","subHeader":"","items":["Genel trafik ve yaya yolu birbirinden ayrılmış mı?","Araçlar için ayrılan kapılardan yaya geçişi yapılmamakta olup yayaların çalışma ortamına giriş-çıkışı için işaretlenmiş ayrı bir kapı bulunmakta mı?","Malzeme taşınan yollarda, yayalar için yeterli ve ayrı bir güvenlik mesafesi bırakılmış mı?","İşletme içi taşıma ve transferler için kullanılan yollar açıkça işaretlenmiş mi?","Nakliye yolları, yükleme ve boşaltma platformları yeterince geniş ve güvenli mi?","Çalışma alanında iç ve dış alan hız limitlerine uyulmakta mı?","Sürücülerin araç kullanma eğitim ve yetkinliği, gerekli sürücü sertifikaları mevcut mu?","Araçların servis ve bakımı düzenli olarak yapılmakta mı?","Tesis içi nakliye planı mevcut mu?","Nakliye araçlarının peronlara girişi yönlendirici işaretlerle organize edilmiş mi?","Tehlikeye yol açabilecek ya da tehlikeli manevralar yapan kimseleri yönlendirmek için el işaretleri ve/veya sözlü iletişim kuruluyor mu?","Yükleme ve boşaltım noktaları güvenli mi?","Araç içi kapalı alanda çalışma süreleri en aza indirgenmiş mi?","Tavan yüksekliği yapılan işe ve kargo transfer araçlarının giriş-çıkışına uygun mu?","Araç giriş-çıkış kapılarının ve pencerelerin genişlik ve yükseklikleri uygun mu?","Araç içi kapalı alanda çalışılırken yeterli aydınlatma sağlanmakta mı?","Araçların ışıklandırma sistemi ve göstergeleri düzgün çalışmakta mı?","Araçların aynaları temiz ve kullanılır vaziyette mi?","Yükleme boşaltma alanları çalışanların düşmesini engelleyecek şekilde korkuluklarla çevrilmiş mi?","Çalışanların büyük araçlar arkasında sıkışmalarını engelleyecek tedbirler alınmış mı?"]},{"title":"KİŞİSEL KORUYUCU DONANIMLAR (KKD)","subHeader":"","items":["Çalışanlar yaptıkları işe uygun KKD kullanılmakta mı?","Çalışanlar için yaptıkları işe ve çalışma koşullarına uygun kıyafetler sağlanmakta mı?","Çalışanlar KKD’lerin gereken çalışma koşullarında sürekli takıyorlar mı?","Çalışanların KKD’lerini nasıl muhafaza edecekleri, temizleyecekleri ve ne sıklıkla değiştirmeleri gerektiği ile ilgili bilgi sahibi mi?","KKD’ler için uygun saklama yerleri mevcut mu?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Çalışanlar iş sağlığı ve güvenliği konusunda eğitim almışlar mı?","Çalışanlar yaptıkları işle ilgili olarak gerekli teknik eğitim ve bilgiye sahip mi?","Tüm çalışanlara enfeksiyon riskini azaltmak için genel hijyen bilgisi verilmiş ve gerekli önlemler alınmış mı?","Çalışanlar biyolojik etkenlerle çalışma sırasında maruz kalabileceği riskler konusunda bilgilendiriliyor mu?","Çalışanlar tehlikeli kimyasallarla çalışma sırasında maruz kalınabilecek riskler ve kimyasallar ile güvenli çalışma konusunda bilgilendiriliyor mu?","Çalışanlar kesilme, batma, yanma vb. nedenler ile oluşan yaralara hangi durumda ve kim tarafından müdahale edileceği konusunda bilgilendiriliyor mu?","Çalışanlar kullandıkları makine, araç ve gereçlerin güvenli kullanımı konusunda eğitiliyor mu?","Çalışanlar sağlık ve güvenlik işaretlerinin anlamları konusunda eğitilmiş mi?","Çalışanlar yangın söndürücüleri kullanmayı biliyorlar mı?","Yüklerin elle taşınmasının da neden olabileceği kas iskelet sistemi hastalıklarına karşı çalışanlar bilgilendirilmiş mi?","Çalışanlar sırt ağrısı, boyun ya da omuz incinmesi ve ayak ya da bacaklarda ağrı gibi kas ve iskelet sistemi hastalıklarına karşı bilgilendirilmiş mi?","Yük taşıma-istifleme işlemlerinin neden olabileceği kas iskelet sistemi hastalıklarına karşı çalışanlar bilgilendirilmiş mi?","İşyeri içerisindeki çalışma alanlarında sigara içilmesi yasaklanmış ve çalışanlar bu konuda bilgilendirilmiş mi?","İşyerinde alkol, madde kullanımını önleyici tedbirler alınmış mı?","Çalışanlar, acil durumlarda ne yapması gerektiğ konusunda bilgilendirilmiş mi?","Acil durumlar (yangın, deprem, ilk yardım gerektiren durumlar vb.)konusunda çalışanlar gerekli eğitimler ve uygulamalara tabi tutulmuş mu?","Eğitim ve bilgilendirme ile ilgili belgeler kayıt altına alınıyor ve kayıtlar uygun şekilde muhafaza ediliyor mu?"]}]},{"templateId":"isg_kule_vincler_kontrol","title":"KULE VİNÇLER İÇİN KONTROL LİSTESİ","runningHeader":"KULE VİNÇLER İÇİN KONTROL LİSTESİ","shortName":"Kule Vinçler Kontrol Listesi (Kurulum / Çalışma / Söküm) (342 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"VERTICAL_TOPIC","formNo":"VNÇ-01","dosyaNo":"İSG-KL-08","sayfaNo":"1-N","actionHeaderLabel":"ALINMASI GEREKEN ÖNLEM","dueDateHeaderLabel":"TAMAMLANMA TARİHİ","footnote":"","sections":[{"title":"MEKANİK TEHLİKELER","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Kule vincin kurulacağı yerin zemin etüdü yapılmıştır ve betonarme altyapısı teknik gerekliliklere hazırlanmıştır.","Kurulumun yapılacağı yer ve mobil vincin çalışma alanı boşaltılarak emniyet şeridi ile güvenli hale getir","Kurulumda kullanılacak mobil vincin kaldırma kapasitesi, kaldırılacak en ağır parça ve bu parçanın kald en uzun mesafe için uygundur.","Mobil vinç ile beraber kullanılacak taşıma aksesuarlarının (halat, kanca, bez sapan, kilit-mapa vb.) peri bakımları ve gözle kontrolleri yapılmıştır. Kaldırma kapasiteleri işe uygun seçilmiştir.","Mobil vincin kaldırma kapasiteleri görünür yerlere yazılı olarak vinç üzerine asılmaktadır.","Kullanılan su terazisi vb. ölçüm cihazları kalibre edilmiştir.","Kule vinç kurulum ekibinde çalışacak personel emniyet kemeri, baret, reflektörlü yelek, iş tulumu, iş el ve iş ayakkabısı vb. kişisel koruyucu donanım kullanmaktadır.","Çelik taban elemanları çatlaklara ve korozyona karşı gözle kontrol edilmiştir ve hassas teraziye kurulmuştur.","Beton denge ağırlıkları çatlaklara karşı gözle kontrol edilmiştir ve kule vincin kaldırma kapasitesine uyg sayıda ve sırada yerleştirilmiştir.","Beton denge ağırlıklarının yerleştirilmesi sırasında malzemeye yön veren çalışanlar malzemenin çarpm ve uzuv sıkışmasına karşı gerekli güvenlik önlemlerini almışlardır.","Kule vinç modüllerinin çatlaklara ve korozyona karşı gözle kontrolü yapılmıştır.","Kule vinç modüllerinin saha içerisinde kuyruk grubu, bom halinde montajı esnasında uzuv sıkışmasına mobil vincin kaldırdığı modülün malzemeye yön veren çalışanlara çarpmasına karşı gerekli güvenlik ön alınmıştır.","Mobil vinç ile taşınacak kule vinç parçalarının ağırlık merkezine göre taşıma bağlantı noktaları belirlenm","Kule vincin gövde modüllerinin, dönüş grubu, kabin ve kule tepesinin montajı yapılırken mobil vincin t parçanın sabitlemesini yapacak ekibin, parça taşınırken çarpmasını engellemek için güvenli bi malzemenin taşınmasını beklemeleri sağlanmaktadır.","Montaj yapan çalışanlar ile mobil vinç operatörü arasında telsiz ile etkin iletişim sağlanmaktadır.","Merdiven basamakları ve platformlarda çatlak, göçük vb. deformasyonlar, engeller bulunmamaktadır.","Merdiven basamak yükseklikleri uygundur ve çalışma platformları yeterli genişliktedir.","Çalışma platformları boyunca malzemelerin düşmesini engelleyecek tekmelikler bulunmaktadır.","Düşmelerini önlemek amacıyla el aletleri için sabitlenmiş, korunaklı bir yer yapılmıştır. İşi biten el aletl platformda bırakılmamaktadır.","Yüksekte çalışmayı gerektiren durumlarda çalışma yerlerine uygun araç ve ekipman ile ç sağlanmaktadır.","Kule vincin gövde, bom ve kuyruk montajları sırasında çalışanlar taşınan malzeme sabitlenmeden üzer çıkmamaktadırlar. Parça sabitlendikten sonra mobil vincin kanca bağlantısını parçanın üzerine sökmektedirler.","Kuyruk grubunun ve bomun mobil vinç ile taşınması sırasında kontrolsüz hareketlerinin önlenm taşınan malzeme ip halat yardımı ile yerdeki bir çalışan tarafından yönlendirilmektedir.","Kule vincin montaj sırasında devrilmesini engellemek için moment kuvvetleri göz önünde bulundurula kuyruk denge ağırlıkları ve bom sırasına uygun şekilde ağırlıkların bir kısmı bomun montajından önce, kısmı ise sonra yerleştirilmektedir.","Kuyruk grubunda ve bomda çalışma alanlarında düşmeyi engelleyecek korkuluklar bulunmakt bakımları yapılmaktadır.","Kuyruk grubu ve bom platformlarında zeminde kayma ve düşmeye neden olabilecek malzeme ve kablo bulunmamaktadır.","Kurulum sahasında kaldırılması mümkün bulunmayan pürüzler ve engebeler dikkat çekecek işaretlenmiştir.","Kurulum sahasında takılmaya neden olabilecek kablolar ve hortumlar bulunmamaktadır.","Hasarlı makine ve iş ekipmanlarının kullanımı engellenmektedir.","Makine ve iş ekipmanlarının (mobil vinç, tork vb.) periyodik bakımları yapılmaktadır.","Makine ve iş ekipmanları kullanma kılavuzlarına uygun şekilde kullanılmaktadır.","Kesici veya delici nitelikteki el aletlerinin açıkta bulundurulması engellenmektedir ve koruyucu iç muhafaza edilmesi sağlanmaktadır.","Tüm makine ve ekipmanlarda gerekli uyarı işaretleri bulunmaktadır.","Makine ve iş ekipmanlarını yetkisiz kişilerin kullanması engellenmektedir."]},{"title":"FİZİKSEL TEHLİKELER","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Gürültü düzeyi uyarı ve tehlike sinyallerini baskılayacak düzeyde değildir.","Çalışanların işe uygun kulak koruyucusu kullanmaları sağlanmaktadır ve bunların kullanımının ta yapılmaktadır.","Kulak koruyucularının bakımı ve uygun şekilde muhafazası sağlanmaktadır.","Rotasyonlu çalışma yaptırılarak çalışanların gürültüye maruz kalma süreleri azaltılmaktadır.","Gün ışığında yapılan çalışmalarda güneş ışığından ve parlak yüzeylerden kaynaklanan yansımalara karş uygun göz koruyucu kullanımı sağlanmıştır.","Karanlıkta yapılan çalışmalarda çalışma sahası yeterince ve uygun konumlandırılan ışık kaynaklar aydınlatılmaktadır.","Tüm alanlarda aydınlatmalar çalışır halde bulunmaktadır.","Çalışma alanları ve geçiş yolları uygun bir şekilde aydınlatılmıştır."]},{"title":"KİMYASAL TEHLİKELER","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Kimyasallara ait güncel malzeme güvenlik bilgi formları mevcuttur ve çalışanların erişimine açıktır.","Tehlikeli kimyasal mümkün ise daha az tehlikeli olanı ile ikame edilmektedir.","Kimyasallar etiketli olarak uygun yerde muhafaza edilmektedir.","Kimyasal atıklar uygun şekilde depolanmaktadır ve imha edilmektedir.","Bütün tehlikeli kimyasallar ağzı kapalı şekilde bulundurulmaktadır ve taşınmaktadır.","Kurulum sırasında kule vince ait dönüş grubu, redüktör, halat vb. teçhizatların yağlanması sıras çalışanlar işin özelliğine uygun eldiven, iş kıyafeti, göz koruyucu, solunum koruyucu kullanmaktadır.","Çalışanlar için kimyasalların kullanıldığı yerlerde işin özelliğine uygun kişisel koruyucu ekipman (eldiven gözlük, yüz siperi, maske vb.) sağlanmıştır.","Korozyon oluşmuş mekanik aksam bağlantılarını çalışır hale getirilebilmesi için kullanılan pas çözücüle çalışırken uygun göz koruyucu, eldiven, solunum koruyucu vb. kişisel koruyucu ekipma kullanılmaktadır.","Tozlu çalışma ortamlarında uygun solunum koruyucu kullanılmaktadır."]},{"title":"TERMAL KONFOR","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Çalışanlara iklim şartlarına ve anlık hava şartlarına uygun, hareket kısıtlanmasına neden olmayacak ve çalışanın sağlığını koruyabilecek uygun iş kıyafetleri sağlanmaktadır.","Rotasyonlu çalışma sağlanarak uygunsuz hava şartlarına maruziyet azaltılmaktadır."]},{"title":"ERGONOMİ","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Çalışanlar fiziksel yapılarına uygun işlerde görevlendirilmektedir.","Eğilerek, bükülerek, omuz hizasının üzerindeki bir noktaya uzanarak, çömelerek, diz üstü ve sırt üstü çalışma gibi kas-iskelet sistemini zorlayan pozisyonlarda çalışılmamaktadır.","İşe uygun araç, gereç ve ekipman belirlenmektedir.","Çalışanlar yüklerin elle taşınmasından doğabilecek kas-iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda bilgilendirilmiştir.","Çalışanların kas-iskelet sistemi maruziyetlerinin azaltılması amacıyla molalar yeterli sıklıkta verilmektedir.","Dinlenme alanı çalışma sahasından ayrı bir yerdedir ve yeterlidir.","Dizleri ve dirsekleri sert yüzeylere karşı korunaklı iş kıyafeti tercih edilmektedir.","Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engellenmektedir."]},{"title":"YANGIN VE PATLAMA","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Kolayca tutuşabilir ve parlayabilir tehlikeli kimyasallar birbirlerinden ayrı depolanmaktadır.","Elektrikli ekipman, statik elektrik gibi ateşleme kaynakları ile patlayıcı kimyasallar aynı yerd bulundurulmamaktadır.","Yangın söndürücüler kolay ulaşılabilirdir ve önünde ulaşılmasını engelleyecek malzemel bulunmamaktadır.","Yangın söndürücüler yeterli sayıdadır, çalışır durumdadır ve periyodik kontrolleri yapılmaktadır.","Yangın söndürme ekipmanları ve bulunduğu yerler Sağlık ve Güvenlik İşaretleri Yönetmeliğine uygun şekilde işaretlenmiştir.","Kule vinç kurulumunda ana elektrik bağlantısı ve topraklama bağlantısı teknik şartlara uygun uzman kişiler tarafından yapılmaktadır.","Yangın ve patlama konularında mücadelede çalışanlara eğitimler verilmektedir ve tatbikatl yaptırılmaktadır.","Kule vinç kabinindeki panoların periyodik bakımları ve kontrolleri yapılmaktadır.","Kule vinç kurulumu yapılan sahada havai elektrik, gaz, buhar vb. hatların tespiti yapılarak vinç çalışma alanı düzenlenmektedir. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir."]},{"title":"ELEKTRİK","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Kullanılan tüm prizler topraklıdır.","Hasarlı fiş ve prizler bulunmamaktadır.","Prizler kapaklıdır ve akım kapasiteleri etiketlenmiştir.","Elektrik panolarında kaçak akım rölesi mevcuttur ve periyodik kontrolleri yapılmaktadır.","Kule vinç kurulumunda ana elektrik bağlantısı ve topraklama bağlantısı teknik şartlara uygun uzman kişiler tarafından yapılmaktadır.","Kule vinç kabinindeki panoların periyodik bakımları ve kontrolleri yapılmaktadır.","Elektrik bağlantıları ile ilgili bakım, onarım ve montaj işlerini yapan çalışanlar uygun KKD ve izole edilmiş el aletleri kullanmaktadır.","Kule vinç kurulumu yapılan sahada havai elektrik hatlarının tespiti yapılarak gerekli önlemler alınmaktadır. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir.","Tüm sigortaların korunaklı yerlerde olması sağlanmaktadır. Elektrik/sigorta kutuları korunaklıdır ve yetkisiz kişilerin erişimleri önlenmektedir.","Kule vincin elektrik bağlantılarına ve aksamına su veya diğer sıvıların temas etmesi engellenmektedir.","Kabloların ekleme yapılarak (kesilip bantlanarak vb.)uzatılması engellenmektedir.","Açık uçlu, hasarlı, yıpranmış elektrik kablolarının kullanılması engellenmektedir.","Acil durumlarda elektrik enerjisinin kolayca kesilebilmesi için panoların önü açık durumdadır.","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmesi engellenmektedir.","Elektrik panolarının önünde yalıtkan paspas bulunmaktadır.","Çalışma sahasında uzatma kablolarının dağınık şekilde olması, yüklere takılması ve yüklerin altında ezilerek kaçaklara neden olması engellenmektedir."]},{"title":"GENEL","subHeader":"KULE VİNÇ KURULUMU KONTROL LİSTESİ","items":["Çalışma alanı temiz ve düzenlidir.","Çalışma alanında sigara içilmesine izin verilmemektedir.","Gürültü seviyesi, aydınlatma düzeyi, sıcaklık, toza maruziyet ölçümleri yapılmıştır.","Hurda ve atık sahası bulunmaktadır.","Rotasyonlu çalışma sağlanmaktadır.","Alınan kararlarda çalışanların katılımı sağlanmaktadır.","Çalışanlar işin özelliği gereği maruz kaldıkları tehlike ve riskler konularında bilgilendirilmektedirler.","İlkyardım ve düzenli sağlık gözetimi sağlanmaktadır.","İlk yardım dolapları mevcuttur ve ilk yardım için eğitilmiş görevli çalışanlar bulunmaktadır.","Acil eylem planı mevcuttur.","Acil durumda gerekli olabilecek telefon numaraları herhangi bir acil durum anında kolaylık bulunabilecek yere asılmıştır.","Yapılan işin özelliğine uygun sağlık ve güvenlik işaretleri ile çalışanlar uyarılmıştır.","Kullanılan alet, teçhizatlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımların bakımı ve uygun muhafazası sağlanmaktadır.","Gerekli çalışmalarda işin özelliğine uygun kişisel koruyucu donanımların kullanılması kontr edilmektedir.","Çalışanların işe giriş muayeneleri ve periyodik kontrolleri yaptırılmaktadır. Tetanos aşısı yapılmaktadır.","İş kazaları ve meslek hastalıkları kayıt altına alınmaktadır ve yasal süresi içerisinde SGK’ bildirilmektedir.","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınmaktadır ve tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşılmaması için gerekli önlemler alınmaktadır.","Çalışanların iş sağlığı ve güvenliği temel eğitimini almaları sağlanmaktadır.","Çalışanlara görev ve sorumluluklarını güvenli şekilde yerine getirmeleri için yeterli süre sağlanmaktadı","Çalışanlar yaptıkları işin özelliğine uygun gerekli eğitim ve bilgiye sahiptirler.","Çalışanlara görev ve sorumlulukları dışında talimat verilmemektedir.","Çalışanlar yetki, sorumluluk ve hedeflerini tam olarak bilmektedirler.","VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ"]},{"title":"MEKANİK TEHLİKELER","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Çalışma sahasında birden fazla kule vinç var ise kesişim bölgeleri emniyetli hale getirilmektedir. Kesişim olduğu durumlarda çarpışmalarını engellemek için vinçler arasında yükseklik farkı bulundurulmaktadır","Çalışma alanı sınırlayıcısı ya da çarpışma engelleyici mekanizma vardır ve çalışır durumdadır.","Kule vincin yetkisi olmayan kişilerce kullanılması engellenmektedir.","Kule vincin Türkçe kullanma kılavuzu bulunmaktadır ve kullanıcıların erişimine açıktır.","Kule vinç ile yapılacak çalışmalar hakkında diğer saha personelleri bilgilendirilmektedir. Şantiye sorum tarafından günlük vinçle yapılacak işlerin programı o günün sabahında operatöre belirtilmektedir.","Operatörün vince çıkması güvenli yollardan sağlanmaktadır. Binadan geçiş yapılıyorsa korunakl yürüme yolu temin edilmektedir.","Kule vinç ile malzeme taşınacak alandan çalışanların geçmesi engellenmekte, taşınan yük çalış üzerinden ve şantiye sahası dışından geçirilmemektedir.","Kule vinç ile beraber kullanılacak taşıma aksesuarlarının (sepet, halat, kanca, bez sapan, kilit-mapa vb. periyodik kontrolleri ve bakımları yapılmaktadır. Kaldırma kapasiteleri işe uygun seçilmektedir.","Yıpranmış ve hasarlı aksesuarların kullanımı engellenmektedir. Derhal imha edilmektedir.","Kule vinç ile yapılan çalışmalarda yükleri bağlama ve boşaltma işlerini yetkili personelin(sapancı ve işar yapması sağlanmaktadır.","Kule vinç ile yapılacak çalışmalarda hava şartları göz önünde bulundurulmaktadır ve hava şartlarına uy taşıma aksesuarlarının kullanılması sağlanmaktadır.","Uzun süren elektrik kesintisi durumlarında askıda kalan yükün mekanik fren yardımıyla zemine indirilm sağlanmaktadır.","Kule vinç ile yapılacak çalışmalarda hava şartları göz önünde bulundurularak, çalışanlara hava şartların uygun iş elbiseleri ve KKD’ler temin edilmektedir.","Operatörün kontrol ekranında anlık rüzgâr hızı okunmaktadır. Rüzgâr hızı saatte 50 km’yi geçtiğinde ku vinç ile çalışma yapılmamakta, 72 km’yi geçtiği zaman rüzgar freni açılarak vinç emniyetli şekilde terk edilmektedir.","Gövdeye teleskop ile modül ekleme işlemleri sırasında vinçle yük taşınması işi durdurulmaktadır ve vin ani hareketler yaptırmaktan kaçınılmaktadır.","Teleskop kullanımında hidrolik sisteminin, hidrolik yağ seviyesinin, pistonunun ve hortumlarının kontr yapılmaktadır.","Kule vincin bağlantı noktaları çatlaklara ve korozyona karşı vince çıkarken ve vinçten inerken operatör tarafından gözle kontrolü yapılmaktadır.","Vinç-bina bağlantı kolları gerekli yüksekliklerde ve sıklıkta yapılmaktadır ve düzenli kontrollerinin yapıl sağlanmaktadır.","Vinç-bina bağlantı kolları korunaklı hale getirilip, amacı dışında kullanılması engellenmektedir.","Yük taşınması işlemleri sırasında malzemeler uygun bağlantı elemanları ile bağlanarak taşın sağlanmaktadır ve ani hareketlerden kaçınılmaktadır.","Kat arasından malzeme taşınması işlerinde(tünel kalıp vb.) platform olmayan bölgelerden ta yapılmasına engel olunmaktadır.","Malzemeler kaldırılırken ya da indirilirken kule vincin halatı aşınmalara karşı beton, çelik vb. sert yüzey temas ettirilmeden işlemlerin yapılması sağlanmaktadır.","Yüzey alanı büyük malzemelerin taşınması sırasında rüzgâr yükü ile malzemenin kontrolden çıkmamas gereken emniyet tedbirleri alınmaktadır.","Genişliği büyük malzemelerin taşınması sırasında güvenli bir mesafeden çalışanların ip halat ile taşınan malzemeye yön vermesi sağlanmaktadır.","Kule vincin limit şalterlerinin periyodik kontrollerinin ve bakımlarının yapılması sağlanmaktadır ve dev dışı bırakılmasına izin verilmemektedir.","Fren sistemlerinin periyodik kontrollerinin ve bakımlarının yapılması sağlanmaktadır, arızalı duru çalıştırılmamaktadır.","Kule vinçte bulunan mekanik acil durum durdurma mekanizmalarının periyodik bakımları yapılmaktad üretici izni olmadan değişiklik yapılmamaktadır.","İnsan taşınmasına uygun olmayan ekipmanlar ile çalışanların taşınmasına engel olunmaktadır.","Kum, tuğla, sıvı malzemeler, sanayi tipi tüp, harç, cam, yalıtım malzemeleri gibi değişik formda ve özel olan malzemelerin uygun taşıma aparatları ile taşınması sağlanmaktadır. (sepet, kova, ağ vb.)","Kule vinç ile taşıma işi yapılırken operatör ile diğer çalışanlar arasında telsiz ile etkin ile sağlanmaktadır.","Taşıma işleri mümkün ise operatörün görüş alanında yapılması sağlanmaktadır.","Vincin korna tertibatı ile gereken durumlarda operatörün etrafa uyarı vermesi sağlanmaktadır.","Taşınan malzemeyi kancadan çıkaracak çalışanların yük iyice yere yaklaşmadan yükün etra bulunmaları engellenmektedir.","Kule vinç ile çalışma yapılmadığı durumda kancasının olabildiğince yükseğe çekilip, rüzgar freni açılara serbest dönüş durumunda bırakılmaktadır.","Operatörün, kule vincin tepesine veya diğer kısımlarına geçmesi gerektiği durumlarda uygun em kemeri takması sağlanmaktadır.","Kule vincin tepesine, kuyruk bitimine ve bomun ucuna kırmızı uyarı ışığı takılmıştır ve çalışır durumdad","Karlı, buzlu havalarda anemometre ve açık havaya maruz limit şalterleri kontrol edilmektedir.","Vincin kaldırma kapasiteleri görünür yerlere yazılı olarak vinç üzerine asılmaktadır.","Ayrıca görevlendirilmiş sapancı ve işaretçi bulunmaktadır.","Operatör sadece işaretçiden aldığı komutlarla hareket etmektedir ve her kim tarafından verilirse verils her dur işaretini daima yerine getirmektedir.","İşaretçi, ceket, baret, kolluk, kol bandı gibi ayırt edici eşyalardan bir veya daha fazlasını giymektedir, u bir işaret aracı taşımaktadır."]},{"title":"FİZİKSEL TEHLİKELER","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Gürültü düzeyi uyarı ve tehlike sinyallerini baskılayacak düzeyde değildir.","Çalışanların işe uygun kulak koruyucusu kullanmaları sağlanmaktadır ve bunların kullanımının ta yapılmaktadır.","Kulak koruyucularının bakımı ve uygun şekilde muhafazası sağlanmaktadır.","Rotasyonlu çalışma yaptırılarak çalışanların gürültüye maruz kalma süreleri azaltılmaktadır.","Gün ışığında yapılan çalışmalarda güneş ışığından ve parlak yüzeylerden kaynaklanan yansımalara karş uygun göz koruyucu kullanımı sağlanmıştır.","Karanlıkta yapılan çalışmalarda çalışma sahası yeterince ve uygun konumlandırılan ışık kaynaklar aydınlatılmaktadır.","Tüm alanlarda aydınlatmalar çalışır halde bulunmaktadır.","Çalışma alanları ve geçiş yolları uygun bir şekilde aydınlatılmıştır."]},{"title":"KİMYASAL TEHLİKELER","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Kimyasallara ait güncel malzeme güvenlik bilgi formları mevcuttur ve çalışanların erişimine açıktır.","Tehlikeli kimyasal mümkün ise daha az tehlikeli olanı ile ikame edilmektedir.","Kimyasallar etiketli olarak uygun yerde muhafaza edilmektedir.","Kimyasal atıklar uygun şekilde depolanmaktadır ve imha edilmektedir.","Bütün tehlikeli kimyasallar ağzı kapalı şekilde bulundurulmaktadır ve taşınmaktadır.","Çalışması sırasında kule vince ait dönüş grubu, redüktör, halat vb. teçhizatların yağlanması sıras çalışanlar işin özelliğine uygun eldiven, iş kıyafeti, göz koruyucu, solunum koruyucu kullanmaktadır.","Çalışanlar için kimyasalların kullanıldığı yerlerde işin özelliğine uygun kişisel koruyucu ekipman (eldiven gözlük, yüz siperi, maske vb.) sağlanmıştır.","Korozyon oluşmuş mekanik aksam bağlantılarını çalışır hale getirilebilmesi için kullanılan pas çözücüle çalışırken uygun göz koruyucu, eldiven, solunum koruyucu vb. kişisel koruyucu ekipma kullanılmaktadır.","Tozlu çalışma ortamlarında uygun solunum koruyucu kullanılmaktadır."]},{"title":"TERMAL KONFOR","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Sıcak ve soğuk havalarda kabinin sıcaklık şartları uygundur.","Aşırı sıcak ya da soğuk hava, yağmur, hava akımı gibi uygunsuz koşullara maruziyetin çalışanlar üzerindeki olumsuz etkisini azaltacak önlemler alınmaktadır.","Çalışanlara iklim şartlarına ve anlık hava şartlarına uygun, hareket kısıtlanmasına neden olmayacak ve çalışanın sağlığını koruyabilecek uygun iş kıyafetleri sağlanmaktadır.","Rotasyonlu çalışma sağlanarak uygunsuz hava şartlarına maruziyet azaltılmaktadır."]},{"title":"ERGONOMİ","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Çalışanlar fiziksel yapılarına uygun işlerde görevlendirilmektedir.","Eğilerek, bükülerek, omuz hizasının üzerindeki bir noktaya uzanarak, çömelerek, diz üstü ve sırt üstü çalışma gibi kas-iskelet sistemini zorlayan pozisyonlarda çalışılmamaktadır.","İşe uygun araç, gereç ve ekipman belirlenmektedir.","Çalışanlar yüklerin elle taşınmasından doğabilecek kas-iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda bilgilendirilmiştir.","Çalışanların kas-iskelet sistemi maruziyetlerinin azaltılması amacıyla molalar yeterli sıklıkta verilmekte","Dinlenme alanı çalışma sahasından ayrı bir yerdedir ve yeterlidir.","Dizleri ve dirsekleri sert yüzeylere karşı korunaklı iş kıyafeti tercih edilmektedir.","Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engellenmektedir."]},{"title":"YANGIN VE PATLAMA","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Ana elektrik bağlantısının ve topraklama bağlantısının periyodik bakım ve kontrolleri yapılmaktadır.","Kule vinç kabinindeki panoların periyodik bakımları ve kontrolleri yapılmaktadır.","Çalışma yapılan sahada havai elektrik, gaz, buhar vb. hatların tespiti yapılarak gerekli önlem alınmaktadır. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir.","Çalışma alanında olası bir yangın riskine karşı yangın söndürücü ekipman bulundurulmaktadır ve son kullanma tarihleri ile basınçları kontrol edilmektedir.","Kabin içinde yangın durumunda kullanılmak üzere yangın tüpü bulundurulmaktadır.","Kum, tuğla, sıvı malzemeler, sanayi tipi tüp, harç, cam, yalıtım malzemeleri gibi değişik formda özellikte olan malzemelerin uygun taşıma aparatları ile taşınması sağlanmaktadır. (sepet, kova, ağ vb.)","Kolayca tutuşabilir ve parlayabilir tehlikeli kimyasallar birbirlerinden ayrı depolanmaktadır.","Elektrikli ekipman, statik elektrik gibi ateşleme kaynakları ile patlayıcı kimyasallar aynı ye bulundurulmamaktadır.","Yangın söndürücüler, kabin içi dahil olmak üzere kolay ulaşılabilirdir ve önünde ulaşılmasını engelleyec malzemeler bulunmamaktadır.","Yangın söndürücüler yeterli sayıdadır, çalışır durumdadır ve periyodik kontrolleri yapılmaktadır.","Yangın söndürme ekipmanları ve bulunduğu yerler Sağlık ve Güvenlik İşaretleri Yönetmeliğine uygun şekilde işaretlenmiştir.","Yangın ve patlama konularında mücadelede çalışanlara eğitimler verilmektedir ve tatbika yaptırılmaktadır.","Kule vinç bulunan sahada havai elektrik, gaz, buhar vb. hatların tespiti yapılarak vinç çalışma a düzenlenmektedir. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir."]},{"title":"ELEKTRİK","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Kullanılan tüm prizler topraklıdır.","Hasarlı fiş ve prizler bulunmamaktadır.","Kabloların ekleme yapılarak (kesilip bantlanarak vb.)uzatılması engellenmektedir.","Açık uçlu, hasarlı, yıpranmış elektrik kablolarının kullanılması engellenmektedir.","Acil durumlarda elektrik enerjisinin kolayca kesilebilmesi için panoların önü açık durumdadır ve acil durdurma butonları çalışır durumdadır.","Prizler kapaklıdır ve akım kapasiteleri etiketlenmiştir.","Elektrik panolarında kaçak akım rölesi mevcuttur ve periyodik kontrolleri yapılmaktadır.","Elektrik bağlantısı ve topraklama bağlantısı teknik şartlara uygun uzman kişiler tarafından yapılmaktadır.","Kule vinç kabinindeki panoların periyodik bakımları ve kontrolleri yapılmaktadır.","Elektrik bağlantıları ile ilgili bakım, onarım ve montaj işlerini yapan çalışanlar uygun KKD ve izole edilmiş el aletleri kullanmaktadır.","Kule vinç bulunan sahada havai elektrik hatlarının tespiti yapılarak gerekli önlemler alınmaktadır. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir.","Kule vincin elektrik bağlantılarına ve aksamına su veya diğer sıvıların temas etmesi engellenmektedir.","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmesi engellenmektedir.","Elektrik panolarının önünde yalıtkan paspas bulunmaktadır.","Çalışma sahasında uzatma kablolarının dağınık şekilde olması, yüklere takılması ve yüklerin altında ezilerek kaçaklara neden olması engellenmektedir."]},{"title":"GENEL","subHeader":"KULE VİNÇ İLE ÇALIŞMA KONTROL LİSTESİ","items":["Çalışma alanı temiz ve düzenlidir.","Çalışma alanında sigara içilmesine izin verilmemektedir.","Gürültü seviyesi, aydınlatma düzeyi, sıcaklık, toza maruziyet ölçümleri yapılmıştır.","Hurda ve atık sahası bulunmaktadır.","Rotasyonlu çalışma sağlanmaktadır.","Alınan kararlarda çalışanların katılımı sağlanmaktadır.","Çalışanlar işin özelliği gereği maruz kaldıkları tehlike ve riskler konularında bilgilendirilmektedirler.","İlkyardım ve düzenli sağlık gözetimi sağlanmaktadır.","İlk yardım dolapları mevcuttur ve ilk yardım için eğitilmiş görevli çalışanlar bulunmaktadır.","Acil eylem planı mevcuttur.","Acil durumda gerekli olabilecek telefon numaraları herhangi bir acil durum anında kolaylık bulunabilecek yere asılmıştır.","Yapılan işin özelliğine uygun sağlık ve güvenlik işaretleri ile çalışanlar uyarılmıştır.","Kullanılan alet, teçhizatlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımların bakımı ve uygun muhafazası sağlanmaktadır.","Gerekli çalışmalarda işin özelliğine uygun kişisel koruyucu donanımların kullanılması kontr edilmektedir.","Çalışanların işe giriş muayeneleri ve periyodik kontrolleri yaptırılmaktadır. Tetanos aşısı yapılmaktadır.","İş kazaları ve meslek hastalıkları kayıt altına alınmaktadır ve yasal süresi içerisinde SGK’ bildirilmektedir.","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınmaktadır ve tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşılmaması için gerekli önlemler alınmaktadır.","Çalışanların iş sağlığı ve güvenliği temel eğitimini almaları sağlanmaktadır.","Çalışanlara görev ve sorumluluklarını güvenli şekilde yerine getirmeleri için yeterli süre sağlanmaktadı","Çalışanlar yaptıkları işin özelliğine uygun gerekli eğitim ve bilgiye sahiptirler.","Çalışanlara görev ve sorumlulukları dışında talimat verilmemektedir.","Çalışanlar yetki, sorumluluk ve hedeflerini tam olarak bilmektedirler.","VİNÇ SÖKÜMÜ KONTROL LİSTESİ"]},{"title":"MEKANİK TEHLİKELER","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Şantiye sorumluları tarafından sökümü yapacak ekip ile beraber söküm programı hazırlanmakt birimler bilgilendirilmektedir.","Söküm işinin yapılacağı yer ve mobil vincin çalışma alanı boşaltılarak emniyet şeridi ile güven getirilmektedir.","Söküm için kullanılacak mobil vincin kaldırma kapasitesinin, kaldırılacak en ağır parça ve bu pa kaldırılacağı en uzun mesafe için uygun olması sağlanmaktadır.","Mobil vinç ile beraber kullanılacak taşıma aksesuarlarının (halat, kanca, bez sapan, kilit-mapa vb.) peri kontrolleri ve bakımları yapılmıştır. Kaldırma kapasiteleri işe uygun seçilmiştir.","Mobil vincin kaldırma kapasiteleri görünür yerlere yazılı olarak vinç üzerine asılmaktadır.","Mobil vincin manevra yapacağı alan boşaltılmıştır ve mobil vinç teknik şartlara uygun kurulmuştur.","Gövdeden teleskop ile modül çıkartma işlemleri sırasında kule vinçle yük taşınması engellenmektedir v vince ani hareketler yaptırmaktan kaçınılmaktadır.","Söküm ekibinde çalışacak personel emniyet kemeri, baret, reflektörlü yelek, iş tulumu, iş eldiveni ve i ayakkabısı vb. kişisel koruyucu donanım kullanmaktadır.","Merdiven basamakları ve platformlarda çatlak, göçük vb. deformasyonlar, engeller bulunmamaktadır.","Yüksekte çalışmayı gerektiren durumlarda çalışma yerlerine uygun araç ve ekipman ile ç sağlanmaktadır.","Söküm yapılırken kule vincin kancası yukarı çekilmekte ve araba üzerine sabitlenmektedir. Kanca üzeri halat, zincir gibi elemanlar bırakılmamaktadır.","Beton denge ağırlıklarının sökümü sırasında malzemeye yön veren çalışanların malzemenin çarpmasın uzuv sıkışmasına karşı gerekli güvenlik önlemlerini almaları sağlanmaktadır.","Mobil vinç ile taşınacak kule vinç parçalarının ağırlık merkezine göre taşıma bağlantı no belirlenmektedir ve belirlenen noktalardan bağlanmaktadır.","Sökümü yapan çalışanlar ile mobil vinç operatörü arasında telsiz ile etkin iletişim sağlanmaktadır.","Gövde, bom ve kuyruk sökümleri sırasında çalışanlar, mobil vincin kanca bağlantısını yaptıktan taşınacak parça üzerinden uzaklaşarak, sabit bir noktandan cıvata-somun veya pim bağlantısını sökme","Kuyruk ve bom sökümünde pim bağlantıları sökülmeden önce kontrolsüz salınımının önlenmesi için gö sökülen parça arasına geçici emniyet halatlarının takılması sağlanmaktadır.","Kuyruk grubunun ve bomun mobil vinç ile taşınması sırasında kontrolsüz salınımının önlenmesi için taş malzeme ip halat yardımı ile yerdeki bir çalışan tarafından yönlendirilmektedir.","Kule vincin söküm sırasında devrilmesini engellemek için moment kuvvetleri göz önünde bulundurular kuyruk denge ağırlıkları ve bom sırasına uygun şekilde ağırlıkların bir kısmı bomun sökümünden önce, kısmı ise sonra sökülmektedir.","Kuyruk grubunda ve bomda çalışma alanlarında düşmeyi engelleyecek korkuluklar bulunmakta bakımları yapılmaktadır.","Kuyruk grubu ve bom platformlarında zeminde kayma ve düşmeye neden olabilecek malzeme ve kablo bulunmamaktadır.","El aletleri ve malzemelerin aşağı düşmesini önleyecek korunaklı alanlar bulunmaktadır, işi biten malzemeler platform üzerinde bırakılmamaktadır.","Kule vinç, mobil vincin kapasitesi ve sahanın uygunluğu oranında mümkün olan büyük parçalar h sökülerek yerde daha küçük parçalara ayrılması sağlanmaktadır. Böylece yüksekte çalışmanın m edilmesi amaçlanmaktadır.","Büyük parçalar halinde sökülen kısımların yerde mobil vinç ile daha küçük parçalara ayrılması sırasında sıkışmasına ve mobil vincin kaldırdığı modülün malzemeye yön veren çalışanlara çarpmasına karşı gere güvenlik önlemleri alınmaktadır.","Denge ağırlıkları dahil bütün kule vinç parçalarının deformasyonlara karşı gözle kontrolleri yapıl parçalar zarar görmeyecek şekilde saklanmaktadır.","Kule vinç parçaları söküldükten sonra oluşabilecek inşaat temel boşlukları emniyet şeridi veya bariyer korunaklı hale getirilmektedir.","Kule vinç parçaları korozyona ve haşeratların kablo vb. teçhizata zarar vermemesi için uygun te alınarak saklanmaktadır.","Söküm sahasında kaldırılması mümkün bulunmayan pürüzler ve engebeler dikkat çekecek işaretlenmiştir.","Söküm sahasında takılmaya neden olabilecek kablolar ve hortumlar bulunmamaktadır.","Hasarlı makine ve iş ekipmanlarının kullanımı engellenmektedir.","Makine ve iş ekipmanlarının(Mobil vinç, tork vb.) periyodik bakımları yapılmaktadır.","Makine ve iş ekipmanları kullanma kılavuzlarına uygun şekilde kullanılmaktadır.","Kesici veya delici nitelikteki el aletlerinin açıkta bulundurulması engellenmektedir ve koruyucu içerisin muhafaza edilmesi sağlanmaktadır.","Tüm makine ve ekipmanlarda gerekli uyarı işaretleri bulunmaktadır.","Makine ve iş ekipmanlarını yetkisiz kişilerin kullanması engellenmektedir."]},{"title":"FİZİKSEL TEHLİKELER","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Gürültü düzeyi uyarı ve tehlike sinyallerini baskılayacak düzeyde değildir.","Çalışanların işe uygun kulak koruyucusu kullanmaları sağlanmaktadır ve bunların kullanımının ta yapılmaktadır.","Kulak koruyucularının bakımı ve uygun şekilde muhafazası sağlanmaktadır.","Rotasyonlu çalışma yaptırılarak çalışanların gürültüye maruz kalma süreleri azaltılmaktadır.","Gün ışığında yapılan çalışmalarda güneş ışığından ve parlak yüzeylerden kaynaklanan yansımalara karş uygun göz koruyucu kullanımı sağlanmıştır.","Karanlıkta yapılan çalışmalarda çalışma sahası yeterince ve uygun konumlandırılan ışık kaynaklar aydınlatılmaktadır.","Tüm alanlarda aydınlatmalar çalışır halde bulunmaktadır.","Çalışma alanları ve geçiş yolları uygun bir şekilde aydınlatılmıştır."]},{"title":"KİMYASAL TEHLİKELER","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Kimyasallara ait güncel malzeme güvenlik bilgi formları mevcuttur ve çalışanların erişimine açıktır.","Tehlikeli kimyasal mümkün ise daha az tehlikeli olanı ile ikame edilmektedir.","Kimyasallar etiketli olarak uygun yerde muhafaza edilmektedir.","Kimyasal atıklar uygun şekilde depolanmaktadır ve imha edilmektedir.","Bütün tehlikeli kimyasallar ağzı kapalı şekilde bulundurulmaktadır ve taşınmaktadır.","Söküm sırasında kule vince ait dönüş grubu, redüktör, halat vb. teçhizatların yağlanması sıras çalışanlar işin özelliğine uygun eldiven, iş kıyafeti, göz koruyucu, solunum koruyucu kullanmaktadır.","Çalışanlar için kimyasalların kullanıldığı yerlerde işin özelliğine uygun kişisel koruyucu ekipman (eldiven gözlük, yüz siperi, maske vb.) sağlanmıştır.","Korozyon oluşmuş mekanik aksam bağlantılarını çalışır hale getirilebilmesi için kullanılan pas çözücüle çalışırken uygun göz koruyucu, eldiven, solunum koruyucu vb. kişisel koruyucu ekipma kullanılmaktadır.","Tozlu çalışma ortamlarında uygun solunum koruyucu kullanılmaktadır."]},{"title":"TERMAL KONFOR","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Çalışanlara iklim şartlarına ve anlık hava şartlarına uygun, hareket kısıtlanmasına neden olmayacak ve çalışanın sağlığını koruyabilecek uygun iş kıyafetleri sağlanmaktadır.","Rotasyonlu çalışma sağlanarak uygunsuz hava şartlarına maruziyet azaltılmaktadır."]},{"title":"ERGONOMİ","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Çalışanlar fiziksel yapılarına uygun işlerde görevlendirilmektedir.","Eğilerek, bükülerek, omuz hizasının üzerindeki bir noktaya uzanarak, çömelerek, diz üstü ve sırt üstü çalışma gibi kas-iskelet sistemini zorlayan pozisyonlarda çalışılmamaktadır.","İşe uygun araç, gereç ve ekipman belirlenmektedir.","Çalışanlar yüklerin elle taşınmasından doğabilecek kas-iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda bilgilendirilmiştir.","Çalışanların kas-iskelet sistemi maruziyetlerinin azaltılması amacıyla molalar yeterli sıklıkta verilmektedir.","Dinlenme alanı çalışma sahasından ayrı bir yerdedir ve yeterlidir.","Dizleri ve dirsekleri sert yüzeylere karşı korunaklı iş kıyafeti tercih edilmektedir.","Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engellenmektedir."]},{"title":"YANGIN VE PATLAMA","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Söküm işleri sırasında ana elektrik bağlantısı ve topraklama bağlantısı teknik şartlara uygun, yetkili kişiler tarafından sökülmektedir.","Kule vinç kabinindeki panoların kontrolleri sağlanarak söküm yapılmaktadır ve korunaklı ha getirilmektedir.","Kule vinç sökümü yapılan sahada havai elektrik, gaz, buhar vb. hatların tespiti yapılarak söküm işlemle planlanmaktadır. Çalışanlar hatların riskleri konusunda bilgilendirilmektedir.","Çalışma alanında olası bir yangın riskine karşı yeterli sayıda yangın söndürücü ekipma bulundurulmaktadır ve son kullanma tarihleri ile basınçları kontrol edilmektedir.","Kolayca tutuşabilir ve parlayabilir tehlikeli kimyasallar birbirlerinden ayrı depolanmaktadır.","Elektrikli ekipman, statik elektrik gibi ateşleme kaynakları ile patlayıcı kimyasallar aynı yerd bulundurulmamaktadır.","Yangın söndürücüler kolay ulaşılabilirdir ve önünde ulaşılmasını engelleyecek malzemele bulunmamaktadır.","Yangın söndürme ekipmanları ve bulunduğu yerler Sağlık ve Güvenlik İşaretleri Yönetmeliğine uygun şekilde işaretlenmiştir.","Yangın ve patlama konularında mücadelede çalışanlara eğitimler verilmektedir ve tatbikatla yaptırılmaktadır."]},{"title":"ELEKTRİK","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Kullanılan tüm prizler topraklıdır.","Hasarlı fiş ve prizler bulunmamaktadır.","Prizler kapaklıdır ve akım kapasiteleri etiketlenmiştir.","Elektrik panolarında kaçak akım rölesi mevcuttur ve periyodik kontrolleri yapılmaktadır.","Elektrik bağlantıları ile ilgili bakım, onarım ve söküm işlerini yapan çalışanlar uygun KKD ve izole edilmi el aletleri kullanmaktadır.","Kule vinç sökümü yapılan sahada havai elektrik hatlarının tespiti yapılarak gerekli önlemler alınmaktad Çalışanlar hatların riskleri konusunda bilgilendirilmektedir.","Tüm sigortaların korunaklı yerlerde olması sağlanmaktadır. Elektrik/sigorta kutuları kilitlenmiş ve yetk kişilerin erişimleri önlenmektedir. Bağlantıların söküldüğü yerler korunaklı hale getirilmektedir.","Kule vincin elektrik bağlantılarına ve aksamına su veya diğer sıvıların temas etmesi engellenmektedir.","Kabloların ekleme yapılarak (kesilip bantlanarak vb.)uzatılması engellenmektedir.","Açık uçlu, hasarlı, yıpranmış elektrik kablolarının kullanılması engellenmektedir.","Acil durumlarda elektrik enerjisinin kolayca kesilebilmesi için panoların önü açık durumdadır.","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmesi engellenmekted","Elektrik panolarının önünde yalıtkan paspas bulunmaktadır.","Elektrik kontrol panosuna ve sigortalara ulaşımı engelleyecek malzemeler ortadan kaldırılmaktadır.","Çalışma sahasında uzatma kablolarının rastgele dağınık şekilde olması, yüklere takılması ve yükle altında ezilerek kaçaklara neden olması engellenmektedir."]},{"title":"GENEL","subHeader":"KULE VİNÇ SÖKÜMÜ KONTROL LİSTESİ","items":["Çalışma alanı temiz ve düzenlidir.","Çalışma alanında sigara içilmesine izin verilmemektedir.","Gürültü seviyesi, aydınlatma düzeyi, sıcaklık, toza maruziyet ölçümleri yapılmıştır.","Hurda ve atık sahası bulunmaktadır.","Rotasyonlu çalışma sağlanmaktadır.","Alınan kararlarda çalışanların katılımı sağlanmaktadır.","Çalışanlar işin özelliği gereği maruz kaldıkları tehlike ve riskler konularında bilgilendirilmektedirler.","İlkyardım ve düzenli sağlık gözetimi sağlanmaktadır.","İlk yardım dolapları mevcuttur ve ilk yardım için eğitilmiş görevli çalışanlar bulunmaktadır.","Acil eylem planı mevcuttur.","Acil durumda gerekli olabilecek telefon numaraları herhangi bir acil durum anında kolaylık bulunabilecek yere asılmıştır.","Yapılan işin özelliğine uygun sağlık ve güvenlik işaretleri ile çalışanlar uyarılmıştır.","Kullanılan alet, teçhizatlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımlarda CE işareti bulunmaktadır.","Tüm kişisel koruyucu donanımların bakımı ve uygun muhafazası sağlanmaktadır.","Gerekli çalışmalarda işin özelliğine uygun kişisel koruyucu donanımların kullanılması kontr edilmektedir.","Çalışanların işe giriş muayeneleri ve periyodik kontrolleri yaptırılmaktadır. Tetanos aşısı yapılmaktadır.","İş kazaları ve meslek hastalıkları kayıt altına alınmaktadır ve yasal süresi içerisinde SGK’ bildirilmektedir.","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınmaktadır ve tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşılmaması için gerekli önlemler alınmaktadır.","Çalışanların iş sağlığı ve güvenliği temel eğitimini almaları sağlanmaktadır.","Çalışanlara görev ve sorumluluklarını güvenli şekilde yerine getirmeleri için yeterli süre sağlanmaktadı","Çalışanlar yaptıkları işin özelliğine uygun gerekli eğitim ve bilgiye sahiptirler.","Çalışanlara görev ve sorumlulukları dışında talimat verilmemektedir.","Çalışanlar yetki, sorumluluk ve hedeflerini tam olarak bilmektedirler."]}]},{"templateId":"isg_laboratuvar_kontrol","title":"TEKİNAK GIDA A.Ş. LABORATUVAR İÇİN KONTROL LİSTESİ","runningHeader":"LABORATUVARLAR İÇİN KONTROL LİSTESİ","shortName":"Laboratuvar Kontrol Listesi (237 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"LAB-01","dosyaNo":"İSG-KL-09","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"","sections":[{"title":"GENEL & İŞYERİ DÜZENİ VE HİJYEN","subHeader":"","items":["Zemin, kayma veya düşmeyi önleyecek şekilde tasarlanmış ve iç ve dış zeminler düzenli olarak kontrol ediliyor mu?","Zeminde çökme, erime vb. deformasyonlar bulunması halinde bunlara yönelik düzeltici çalışmalar yapılıyor mu?","Tüm cam yüzeyler uygun şekilde monte ediliyor ve yüzeyler üzerinde kırık ve çatlak gibi hatalar bulunması durumunda yenileri ile değiştiriliyor mu?","Çalışanların yürüdüğü yerlerde küçük engellerin bulunması engelleniyor mu?","Zemin yüzeylerinde ve kapı eşiklerinde düz olmayan, engebeli, pürüzlü bölgeler, delikler, döküntüler vb. bulunması halinde bunlara yönelik düzeltici çalışmalar yapılıyor mu?","Zeminde takılıp düşmeye neden olabilecek gereksiz malzemelerin bulunması engelleniyor mu?","Keskin uçlu köşelere karşı önlem alınmış mı?","Çalışanların yeme-içme, barınma gibi temel ihtiyaçları için uygun donanımlı alanlar ayrılmış mı?","Laboratuvar tezgahları su geçirmez ve dezenfektana karşı dayanıklı, kolay temizlenebilir malzemelerle kaplanmış mı?","Zemin yüzeyleri temiz ve düzenli mi?","Çalışma ortamındaki aletler, malzemeler, atıklar, vb. düzenli mi?","İşyerinin temizliği düzenli olarak yapılıyor ve çalışma ortamında, hijyen açısından gerekli şartlar sağlanıyor mu?","Laboratuvarda çalışıldıktan sonra çalışma ortamı kontaminasyonu engellemek için temizleniyor ve dezenfekte ediliyor mu?","Temizlik yapılan alanda kaymayı önlemek için gerekli önlemler alınıyor mu?","Temizlik/yıkama vb. yapılırken “Dikkat Kaygan Zemin” levhası konuluyor mu?","Tozun yere çökmesi nedeniyle kaygan hale gelen yerler düzenli olarak temizleniyor mu?","Toz veya malzeme artıklarının yerlerde veya taban kenarlarında birikmesi önleniyor mu?","Laboratuvardaki her çalışanın ellerini yıkayabileceği lavabolar mevcut ve bu lavabolarda gerekli hijyen şartları sağlanmakta mıdır? İş bitiminde veya laboratuvarı terk ederken uyulmak üzere el yıkama talimatı mevcut mu?","İşyeri içerisindeki çalışma alanlarında sigara içilmesi yasaklanmış ve çalışanlar bu konuda bilgilendirilmiş mi?","Düzenli olarak haşere kontrolü yapılıyor mu?","Laboratuvarda merdiven bulunması halinde, tırabzan ayakları arasında uygun aralıklarla dikmeler veya düşmeyi önleyecek kapalı bloklar mevcut mudur?","Laboratuvarlara görevli personel dışında giriş-çıkış engellenmiş mi?","Yüksek yerlere yerleştirilmiş nesnelerin hepsi düşmelerini engelleyecek şekilde emniyete alınmış ya da sabitlenmiş mi?","Tüm dolaplar duvarlara uygun şekilde sabitlenmiş mi?","Raflar, duvarlara ve birbirlerine monte edilmiş ve uygun bağlantı elemanlarıyla devrilmeleri engellenmiş mi?","Bütün laboratuvarlarda göz duşu ve güvenlik duşu bulunuyor mu?","Güvenlik duşları ve göz duşları kullanılabilir durumda ve herkesin görebileceği şekilde işaretlenmiş mi?","Güvenlik duşları ve göz duşlarının periyodik bakımları yapılıyor mu?"]},{"title":"MAKİNELER, EL ALETLERİ VE YARDIMCI APARATLAR","subHeader":"","items":["Makina, araç ve gereç tedariğinde CE işaretli olanların alınması sağlanıyor mu?","Makineler için üretici firmadan, Türkçe kullanım kılavuzları temin edilmiş mi ve makineler bu kılavuza uygun olarak kullanılıyor mu?","Cihazların üreticiden temin edilen kullanım kılavuzları doğru ve güvenli kullanım, bakım, vb. konularda bilgi edinmek için yeterli mi ve yeterli olmadığı düşünüldüğü durumlarda ek kullanma talimatları sağlanmış mı?","Kesici veya delici nitelikteki alet veya ekipmanların açıkta bulundurulması engelleniyor ve koruyucu içerisinde muhafaza edilmesi sağlanıyor mu?","Kesici veya delici alet veya ekipmanlar uygun aralıklarla, kullanım öncesi ve sonrasında kontrol ediliyor mu?","Tüm alet veya ekipmanların tasarım amaçlarına uygun yönde kullanılması sağlanıyor mu?","Bütün makinalarda gerekli uyarı işaretleri bulunuyor mu?","Bütün makinaların etrafında çalışma için yeterli alan mevcut mu?","Tüm alet ve gereçlerin kullanımında gerekli hijyen şartları sağlanıyor mu?","Kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde kullanılıyor mu?","Makinelerin uygun makine koruyucuları var mı?","İşveren makine koruyucularının çalışanlar tarafından uygun olarak kullanıp kullanılmadığını kontrol ediyor mu?","Özellikle hareketli parçaları olan makineler/aletler, üreticisinin talimatları doğrultusunda koruma panelleri veya ışık ızgarası vb. önlemler ile koruma altına alınmış mı?","İçerisinde ve parçalarında dönen aksamları bulunan elektrikli aletler ile yapılan çalışmalar sırasında gerekli önlemler alınıyor mu?","Çalışanların makine koruyucularını açınca makineyi durduran sensörleri devre dışı bırakmalarını önlemek amacıyla gerekli kontrol yapılıyor mu?","Makinaların kazara/istemeden çalıştırılması engelleniyor ve makinaların acil durdurma mekanizmaları bulunuyor mu?","Makinalarda bulunan acil durum durdurma butonu çalışıyor mu ve acil durum durdurma butonu uygun periyotlarla denenmekte mi?","İmalatçının talimatları doğrultusunda tüm makinelerin günlük bakımları ve periyodik kontrolleri yapılıyor mu?","Özel cihaz, el aletleri ya da teknik aparatların sadece özel eğitim almış çalışanlar tarafından ve gerekli önlemler alınarak kullanılması sağlanıyor mu?","Lazer ile çalışan cihaz, el aletleri ya da teknik aparatlar sadece özel eğitim almış çalışanlar tarafından gerekli KKD kullanılarak, kendisinin ve diğer çalışanların ışınlara maruz kalmasından kaçınılarak gerekli önlemler alınarak kullanılıyor mu?","Hata tespit edilen ekipmanların kullanılmaması ve bu konuda etiketlenmesi sağlanıyor mu?","Basınç ile çalışan laboratuvar cihazları güvenilir mi, malzeme sıçraması ya da sızdırması gözlenmemesi için gerekli önlemler alınıyor mu?","Gaz ile çalışan laboratuvar cihazları güvenilir mi, malzeme sızdırması gözlenmemesi için gerekli önlemler alınıyor mu?","Cihazların valfleri düzenli olarak kontrol ediliyor mu?","Çeker ocakların periyodik bakımları yapılıyor mu?","Çeker ocakların performansları ölçümlerle kontrol ediliyor ve gerektiğinde filtreleri temizleniyor mu?","Bakım veya kalibrasyon yapılması gibi çeker ocakların kullanılmadığı durumlarda, çeker ocakların kullanılmadığına dair etiket yapıştırılıyor mu?","Çeker ocak üzerinde mevcut hava akış göstergesi bulunuyor mu?","Civalı termometreler yerine civasız termometreler kullanılıyor mu?","Tüm vakum pompaları ve cihaz boruları, emniyetli durumda ve güvenlik kemeri ile sabitlenmiş mi?","Pipetlerle kimyasal alımı puar gibi mekanik gereçler kullanılarak yapılıyor mu?"]},{"title":"KİMYASAL ETKENLER","subHeader":"","items":["Tek kullanımlık pipetler kullanıldıktan sonra atılıyor mu?","İşveren, Kimyasal Riskler konusunda bilgi sahibi ve çalışanlarını bu risklerle ilgili bilgilendirmiş mi?","Kimyasalların mevzuata uygun güvenlik bilgi formları bulunuyor ve tüm personelin ulaşımına açık mı?","Bütün kimyasal kaplarının üzerinde kimyasalların isimlerini, son kullanma tarihlerini ve ilgili tehlikelerini gösteren etiketleri bulunmakta mı?","Bütün kimyasal kaplarının üzerindeki işaretlemeler ilgili mevzuata uygun mu?","Tehlikeli kimyasallar yerine tehlikeli olmayan veya daha az tehlikeli olanların kullanılması ve satın alma yapılırken daima tehl ikeli olmayan veya daha az tehlikeli kimyasalların satın alınması sağlanıyor mu?","Çalışanların sağlığını ciddi şekilde tehdit edebilecek fiziksel özelliklere (örn. sprey veya toz halindeki ) sahip kimyasallar yerine daha güvenli (örn. sıvı veya granül halindeki) kimyasalların kullanılması ve bu tercih her satın alma işleminde kontrol edilmesi sağlanıyor mu?","Çalışanlar, laboratuvar koşullarına uygun kullanma kılavuzu bulunmayan ya da kullanma talimatı henüz hazırlanmamış tehlikeli kimyasalları kullanmamaları konusunda bilgilendirilmiş mi?","Kimyasal maddelerin saklama koşullarına uyuluyor, bu malzemeler ısı, ışık ve diğer malzemelerden uzakta muhafaza ediliyor mu?","Laboratuvarda uygun şekilde yerleştirilmiş ve yeterli sayıda gaz dedektörleri bulunuyor mu?","Oksit bileşeni içeren kimyasallar belirli zamanlarda yenilenmekte, raf ömrü bitenler kurallara göre bertaraf edilmekte mi?","Tüm kimyasal kapları kapalı tutuluyor mu?","Kimyasalların uzaklaştırılması ile ilgili mevzuata uygun özel prosedür uygulanıyor mu?","Kimyasal ile çalışıldığında çeker ocak kullanılması sağlanıyor mu?","İlgili mevzuatta maruziyet sınır değeri belirlenmiş olan maddelerin bu değerin altında olduğu periyodik olarak işyeri ortam ölçümleri ile kontrol ediliyor mu?","Bir kimyasalın dökülmesi ve yayılması durumunda tüm çalışanlar ne yapılması gerektiği hakkında bilgilendirilmiş mi?","Çalışanların, kimyasal maddeler ile çalışma sırasında cilt, göz, solunum vb. temasını önleyecek şekilde uygun nitelikte kişisel koruyucu donanımları (eldiven, maske vb.) kullanması sağlanıyor mu?"]},{"title":"BİYOLOJİK ETKENLER","subHeader":"","items":["Biyolojik etkenlere maruz kalan veya kalabilecek çalışan sayısının mümkün olan en az sayıda tutulması için gerekli organizasyonel düzenlemeler yapılıyor mu?","Çalışma süreçleri ve teknik kontrol önlemleri, biyolojik etkenlerin ortama yayılmasını önleyecek veya ortamda en az düzeyde bulunmasını sağlayacak şekilde düzenlenmiş mi?","Tıbbi ve biyolojik atıkların gerektiğinde uygun işlemlerden geçirildikten sonra çalışanlar tarafından güvenli bir biçimde toplanması, depolanması ve işyerinden uzaklaştırılması, güvenli ve özel kapların kullanılması da dâhil uygun yöntemlerle yapılıyor mu?","Çalışanların, biyolojik etkenlere maruz kalabileceği alanlarda yiyip içmeleri engelleniyor mu?","Tüm laboratuvar personeli doku/kan örneği/vücut sıvıları ile çalışma konusunda yeterli eğitime sahip mi?","Tüm laboratuvar personeli olası enfeksiyon riskleri ve önleyici tedbirler hakkında bilgilendirilmiş mi?","Olası bir bulaşıcı hastalık vakası yaşanması durumunda uygulanacak program mevcut mu?","Çalışanların, biyolojik maddeler ile çalışma sırasında cilt, göz, solunum vb. temasını önleyecek şekilde uygun nitelikte kişisel koruyucu donanımları (eldiven, maske vb.) kullanması sağlanıyor mu?","Çalışanlar, iğne, şırınga, neşter gibi tıbbi ekipmanların doğru kullanımı, depolanması ve uzaklaştırılması hakkında gerekli eğitimleri almışlar mı?","Tek kullanımlık, uçları kilitli iğne ve şırıngalar kullanılması sağlanıyor mu?","Tek kullanımlık olmayan pipetler tekrar kullanılmadan önce otoklavda sterilize ediliyor mu?","Santrifüjde numune tüpü kırılması halinde santrifüj tekrar kullanılmadan önce yıkanıp tamamen sterilize ediliyor mu?","Enfeksiyonlu olduğu bilinen bir örnekle çalışıldıktan sonra çalışanın üzerindeki önlüğün ayrı olarak uzaklaştırılması için gerekli önlemler alınıyor mu?","Alınan örneklerin, ayrı sızdırmaz poşetlere konulması için gerekli düzenlemeler yapılıyor mu?"]},{"title":"FİZİKSEL ETKENLER","subHeader":"","items":["Bütün alanlar iyi aydınlatılılıyor, pencere alanı yeterince büyük ve doğal aydınlatmadan yeterince faydalanılıyor mu?","Aydınlatma armatürlerinden / donanımlarından ya da pencerelerden kaynaklanan göz kamaştırıcı parıltılardan kaynaklanan riskler önlenmiş mi?","Çalışma alanında temiz hava akımı bulunuyor ve tüm alanlar düzenli olarak havalandırılıyor mu?","Tüm alanlardaki mevcut iklimlendirme cihazlarının kontrolleri düzenli aralıklarla yaptırılıyor mu?","Laboratuvar hava ortamına yayılmış gaz, parçacık gibi hava kirliliğini dışarı atarak çalışma ortamı havasını daima temiz tutacak düzeyde doğal havalandırma veya daima çalışır durumda cebri havalandırma sistemi var mı?","Çalışma ortamı sıcaklığının çok soğuk ya da çok sıcak olması engelleniyor mu?","İşyeri içerisindeki sıcaklık ve nem, rahatsızlık vermeyecek düzeyde tutuluyor mu?","Tavandan, duvarlardan ya da zeminden su sızıntısı bulunmuyor mu?","Duvarlarda, zeminde ya da tavanda daha önceden meydana gelmiş olan rutubetten kaynaklı renk bozulması bulunmuyor mu?","İnsanlardan, makine veya donanımlardan kaynaklanabilecek veya dış ortam kaynaklı gürültünün rahatsız edici düzeyde olması engelleniyor mu?","Gürültüden kaynaklanan maruziyet ölçümleri periyodik olarak yapılıyor mu?","Gürültü maruziyet ölçüm değerleri Çalışanların Gürültü ile İlgili Risklerden Korunmalarına Dair Yönetmeliğindeki limit değerlerinin altında mı?","Gürültü maruziyet ölçüm değerlerinin sonuçları Çalışanların Gürültü ile İlgili Risklerden Korunmalarına Dair Yönetmeliğindeki limit değerlerinin üstünde ise yönetmelikte belirtilen önlemler alınıyor mu?","Makine veya donanımlardan kaynaklanabilecek titreşimin rahatsız edici düzeyde olması engelleniyor mu?","Titreşimden kaynaklanan maruziyet ölçümleri periyodik olarak yapılıyor mu?","Titreşim maruziyet ölçüm değerleri Çalışanların Titreşim ile İlgili Risklerden Korunmalarına Dair Yönetmeliğindeki limit değerlerinin altında mı?","Titreşim maruziyet ölçüm değerleri Çalışanların Titreşim ile İlgili Risklerden Korunmalarına Dair Yönetmeliğindeki limit değerlerinin üstünde ise yönetmelikte belirtilen önlemler alınıyor mu?"]},{"title":"YANGIN- PATLAMA- ACİL DURUMLAR","subHeader":"","items":["İşyerinde, acil durum planı hazırlanmış ve laboratuvar için muhtemel tüm acil durumlar (yangın, patlama, tehlikeli kimyasal madde yayılımı, doğal afet, sabotaj ihtimali vb.) belirlenmiş mi?","Laboratuvarın tehlike sınıfı göz önünde bulundurularak, uygun sayıda yangınla mücadele, ilkyardım ile arama kurtarma ve tahliye konularında ekipler oluşturulmuş mu?","Tüm çalışanlar acil durum ekipleri hakkında bilgilendirilmiş mi?","Yangın söndürme ekipmanlarının ve ilkyardım malzemelerinin bulunduğu yerler ile kaçış yollarını gösteren tahliye planı mevcut mu?","Tahliye planı tüm çalışanlarca kolay görülebilir ve ulaşılabilir bir yerde asılı mı?","Yeterli sayıda ve uygun tipte yangın söndürücü mevcut ve son kullanma tarihleri ve basınçları kontrol ediliyor mu?","Acil çıkış yolları ve kapıları Güvenlik ve Sağlık İşaretleri Yönetmeliğine uygun işaretlenmiş mi?","Yangın merdivenine açılan acil çıkış kapıları kilitli olmayıp dışa doğru açılacak şekilde tasarlanmış mı?","Acil çıkış kapılarına ulaşımı engelleyecek faktörler ortadan kaldırılmış ve yangın merdivenlerinin amacı dışında kullanılması engelleniyor mu?","Acil duruma neden olan olaya ilişkin iletişime geçilecek (yangın, gaz kaçağı, deprem vb.) telefon numaraları görünür yer(ler)e asılmış mı?","Acil durum uyarı sisteminin (sesli ve ışıklı uyarı) çalışır durumda olması sağlanıyor mu?","Kapı ve kaçış yollarını gösteren acil durum levhaları uygun yerlere yerleştirilmiş ve yangın merdiveninde ışıklandırma sağlanmış mı?","Çalışanlar, acil durumlarda ne yapması gerektiği konusunda bilgilendirilmiş mi?","Gaz algılama, gaz kesme ve uyarı tesisatı mevcut mu?","Yangın ve duman algılama sistemi, yağmurlama sistemi bulunmakta, periyodik kontrolleri yapılmakta ve çalışır durumda mı?","İlkyardım gerektirecek durumlarda, bu konuda uygun donanıma sahip ve gerekli eğitimleri almış yeterli sayıda çalışan bulunmakta mı?","İlkyardım dolabının bulunduğu yer uygun şekilde işaretlenmiştir ve ilk yardım dolabı tüm çalışanların ulaşabilecekleri bir yerde bulunmakta mı?","İlkyardım dolabı içerisindeki malzemeler uygun nitelikte ve sayıda mı?","Ateş kaynağı ile yapılan işler ayrı bir bölümde sadece işi yapmakla yetkili, eğitimli çalışanlar tarafından yapılması sağlamak için gerekli tedbirler yönetim tarafından alınmış mı?","Kimyasal içerikleri nedeniyle alevlenebilir ürünler; ısı, ışık ve diğer malzemelerden uzakta ve güvenlik bilgi formuna/ talimatlara uygun şekilde muhafaza ediliyor mu?","Laboratuvar kapıları ısıyı ve alevleri iletmeyecek şekilde yalıtkan malzemeden yapılmış özel kapılar mı?","Kullanılan gazın özelliği dikkate alınarak, tablolar, anahtarlar, prizler, borular gibi bütün elektrik tesisatı ilgili yönetmeliklere ve ilgili standartlarına uygun olarak tasarlanmış ve tesis edilmiş mi?","Gaz silindirlerinin bulunduğu odalarda ve çalışıldığı cihazlarda herhangi bir tehlike anında gazı kesecek olan ana kapama vanası ile elektrik akımını kesecek ana devre kesici ve ana elektrik panosu, gaz silindirlerinin bulunduğu ve kullanıldığı ortamlar dışında kolayca ulaşılabilecek bir yerde bulunmakta mı?"]},{"title":"ATIK YÖNETİMİ","subHeader":"","items":["İşveren tehlikeli atık üretimini en az düzeye indirecek tedbirleri almak için gerekli düzenlemeleri yapıyor mu?","Laboratuvar personeli, atık yönetimi prosedürleri konusunda bilgilendirilmiş mi?","Kimyasal atıkların kesinlikle kanalizasyon sistemine boşaltılmaması, evsel atıklarla karıştırılmaması için gerekli düzenlemeler yapılıyor mu?","Tehlikeli kimyasal atıklar ve tıbbi atıkların yalnızca geçici olarak depolanması sağlanıyor mu?","Atık kapları; kimyasal atıklar, tıbbi/biyolojik atıklar, kesici atıklar gibi sınıflandırılmış mı?","Kırık camlar için kullanılabilir durumda bir kap bulunmakta mı?","Atık kapları; türlerine göre ilgili mevzuatlarda belirtildiği gibi etiketleniyorlar mı?","Tüm atıklar sızdırmaz, delinmez kaplarda muhafaza ediliyor mu?","Atık kapları seçilirken, içindeki atıklarla reaksiyon vermeyecek ya da erime göstermeyecek kapların seçilmesi sağlanıyor mu?","Atık kapları kapalı tutulması, yalnızca içine madde atılırken açılması sağlanıyor mu?","Kullanılmış iğneler gibi kesici ve delici özelliği olan tıbbi atıklar, diğer tıbbi atıklardan ayrı olarak ilgili yönetmelikte belirtilen koşullarda toplanıyor mu?","Tıbbi atıklar, diğer atıklardan ayrı olarak ve saklanması, taşınması gibi durumlar için ilgili mevzuatda ayrı ayrı belirtilen koşullarda muhafaza ediliyor mu?","Tıbbi atıklar ilgili mevzuatta belirtildiği gibi etiketleniyor mu?","Tıbbi atıkların uzaklaştırılmasında lisanslı tıbbi atık toplama firması ile çalışılıyor mu?","Çeker ocakların içinde ya da kimyasal depo alanlarında atık maddelerin depolanmaması için gerekli önlemler alınmış mı?","Tehlikeli kimyasal atıklar ve boş gaz silindirleri uygun kap ve ortamlarda geçici olarak depolanmakta ve hemen bertaraf firmalarına teslim edilmekte mi?","Özel taşıma ve imha prosedürü gerektiren çöpler, ayrı ayrı ve farklı renklerdeki atık poşetlerinde saklanıyor ve uzaklaştırılıyor mu?","Kontamine atıkların atılmadan önce otoklavda sterilize edilmeksi veya yakılması sağlanıyor mu?"]},{"title":"DEPOLAMA","subHeader":"","items":["Depolama alanı ayrı bir yerde ve sürekli kontrol ediliyor mu?","Depolama alanlarına görevli personel dışında giriş- çıkış engelleniyor mu?","Tüm dolaplar duvarlara uygun şekilde sabitlenmiş mi?","Raflar; duvarlara ve birbirlerine monte edilmiş, uygun bağlantı elemanlarıyla devrilmeleri engellenmiş mi?","Ekipmanlar, ağır olanlar alt raflarda, hafifler üst raflarda yer alacak şekilde istiflenmiş mi?","Kimyasal maddeler göz seviyesinin üzerindeki raflara yerleştirilmemekte mi?","Aşındırıcı kimyasallar daha alçak raflarda tutulmakta mı?","Yüksek yerlere yerleştirilmiş nesnelerin hepsi düşmelerini engelleyecek şekilde emniyete alınmış ya da sabitlenmiş mi?","Cam malzemeler çarpılmayacak ve devrilmeyecek şekilde muhafaza ediliyor mu?","Buzdolaplarının ve depolama raflarının üzerinde, bulunan kimyasalların listeleri ve tehlikeleri yazılmış mı?","Kapılarda görünecek şekilde gerekli tehlike işaretleri bulunuyor mu?","Depolama alanında kimyasalların güvenlik bilgi formları bulunuyor mu?","Laboratuvarlarda maddeler depolanmadan önce tehlike sınıflarına göre gruplandırılmış mı?","Dolaplar depolanacak kimyasal maddelerin özelliklerine göre alınmış ve düzenlenmiş mi?","Depolama rafları, direk güneş ışığından ve açık alev kaynağından uzak tutuluyor mu?","Gereksiz, kullanılmayan ve son kullanma tarihi geçmiş kimyasallar laboratuvarlardan ve depolama alanlarından kaldırılması sağlanıyor mu?","Yanıcı kimyasalların depolandığı alanda depolama hacmi belirlenmiş ve limitlerin geçilmemesi sağlanıyor mu?","Yanıcı malzemeler ateşleme kaynağından uzakta depolanıyor ve kullanılıyor mu?","Yanıcı sıvıların toplu miktarlarda depolanmasının uygun dolaplarda yapılması sağlanıyor mu?","Cam veya plastik kaplarda açık raflarda saklanan yanıcı malzemelerin izin verilen limit miktarda olması sağlanıyor mu?","Kimyasal madde ya da gaz silindirleri depolama alanlarında kıvılcım oluşturacak kaynaklar bulunmaması sağlanıyor mu?","Gaz silindirleri kullanılmadıkları ve taşınmadıkları zaman özel bir alanda standardına uygun olarak depolanıyor mu?","Gaz silindirleri özel araç ile zincirlenerek taşınıyor mu?","Gaz silindirleri depolama alanının sabit bir noktasına standartlarda belirtilen yüksekliğinden zincirlerle bağlanarak depolanıyor mu?","Gaz silindirleri yüksek sıcaklıktan uzakta depolanıyor mu?","Dolu ve boş gaz silindirleri ayrı ayrı depolanıyor mu?"]},{"title":"ELEKTRİK","subHeader":"","items":["Ana elektrik panosunda sigorta bulunuyor mu?","Tüm elektrik panoları ilgili mevzuata ve standartlara uygun olarak işaretlenmiş mi?","Kaçak akım rölesi ana elektrik hattına bağlanmış mı?","Tüm sigortaların korunaklı yerlerde olması sağlanıyor mu?","Elektrik/sigorta kutuları kilitlenmiş, yetkisiz kişilerin erişimleri önleniyor mu?","Şalter, devre anahtarı, “AÇ/KAPA” düğmeleri gibi unsurlar yerinde ve çalışır vaziyette mi?","Elektrikli alet/ekipmanlar, üreticilerce sağlanan Türkçe kullanım kılavuzlarında belirtilen hususlara uygun şekilde kullanılmakta mı?","Elektrikli donanımların ve elektrik sisteminin bakım ve onarımı belirli periyotlarla yapılıyor mu?","Elektrikli ekipmanların ıslak ortam, su ve kimyasal içerikli ürünler ile temas ettirilmemesi sağlanıyor mu?","Elektrikli donanım, ıslak/ nemli halde iken ve/veya ıslak/ nemli ellerle ve giysilerle kullanılmaması sağlanıyor mu?","Hasar görmüş fiş ve prizler bulunmaması sağlanıyor mu?","Çalışanlar hasar görmüş prizleri, yanlış bağlanmış soketleri hasarlı kabloları fark ettiğinde yetkili bir kişiye haber veriyorlar mı?","Açıkta kablo bulunmaması ve prizlerin sağlamlığı düzenli olarak kontrol ediliyor mu?","Elektrik iletim hatlarında yalıtımı hasar görmüş ve kabloların açığa çıktığı herhangi bir noktanın bulunmaması sağlanıyor mu?","Kesik ve birbirine sonradan eklenmiş elektrik kabloları kullanılmamakta mı?","Elektrikli donanımlar amacı dışında, uygunsuz olarak kullanılmıyor mu?","Elektrik sistemlerine tehlikeli bir yakınlıkta çalışılmamakta mı?","Elektrik sisteminde uygun topraklama yapılmış mı?","Taşınabilir iletkenlerin kullanılması gereken yerlerde, yeterli sayıda ve uygun şekilde topraklanmış elektrik prizleri bulunmakta mı?","Elektrikli ekipmanlara müdahale ve bakım onarım işlemlerinde uygun kişisel koruyucu donanımlar kullanılıyor mu?","Elektrikli cihazların yanında yanıcı ve patlayıcı malzemeler bulundurulmaması sağlanıyor mu?","Çalışanların erişebileceği yerlerde bulunan tevzi tabloları, panoları ile kontrol tertibatı ve benzeri tesisat, kilitli dolap veya hücre içine konulmuş ve bunların tabanı, elektrik akımı geçirmeyen malzeme ile kaplanmış mı?","Bir grup prize(3’lü grup priz vb.) normalden fazla sayıda elektrikli alet bağlanmamakta ve grup prizler birbirine bağlanarak kullanılmaması sağlanıyor mu?","Tüm taşınabilir elektrikli ekipmanlar periyodik olarak test edilmiş ve test tarihleri etiketlerine yazılmakta mı?"]},{"title":"ERGONOMİ","subHeader":"","items":["Çalışanların uzun süre aynı pozisyonda veya fiziksel anlamda zorlayıcı çalışmaları (ağır yük kaldırma dahil) engelleniyor mu?","Çalışanların, işlerini yaparken çok uzak mesafelere uzanmak zorunda kalmaları engelleniyor mu?","Çalışma ortamı çalışanların kolaylıkla hareket edebileceği alana sahip mi?","Çalışanlara, yaptıkları işe uygun masa, sandalye veya destek ekipman sağlanmış mı?","Günlük çalışma süresi boyunca yapılan işin gereği vücudun belli bir bölgesi sabitken diğer bölgesi ile çok sık ve uzun süreli tekrarlanan hareket yapılıyorsa veya uzun süreli aynı pozisyonda çalışılıyor ya da ayakta kalınıyorsa görev değişimi veya belli aralıklarla vücut dinlendirilmesi yapılıyor mu?","Depo da dahil tüm alanların iç düzenlemesi yapılmış, aşırı uzanma gereksinimleri ortadan kaldırılmış ve tüm eşya veya malzemelerin kolay ulaşılabilir olması sağlanmış mı?","Pipetle çekme, kapak açma gibi el, ön kol, başparmak ve parmakların yineleme hareketleri gibi aşırı zorlanmaya yol açan uygulamalar azaltılmış, rotasyon olması sağlanmış mı?","Uzun süre ayakta çalışma durumlarının olmaması için ayaklık ya da sandalye takviyesi yapılmış mı?","Laboratuvarlarda kullanılan sandalyeler ergonomik mi?","Elle taşınamayacak kadar ağır yüklerin çalışanlarca kaldırılması engelleniyor mu?","Yüklerin elle taşınmasından doğabilecek kas iskelet sistemi rahatsızlıkları ile yükleri doğru ve güvenli kaldırma konusunda çalışanlar bilgilendiriliyor mu?","Sırt ve bel incinmesi riski oluşturabilecek yüklerin itilmesini ya da çekilmesini sağlayacak uygun taşıma araçları sağlanıyor mu?"]},{"title":"KİŞİSEL KORUYUCU DONANIM (KKD)","subHeader":"","items":["Laboratuvardaki tüm riskler göz önünde bulundurularak, uygun çeşitlilikte ve miktarda koruyucu donanımlar temin edilmiştir ve kullanıma hazır mı?","Bütün çalışanlar çalışma esnasında uygun kişisel koruyucu donanımlarını kullanıyorlar mı?","Gerekli kişisel koruyucu donanım kullanılması için uyarılar bulunuyor mu?","Kişisel koruyucu donanımlar CE işaretine sahip mi ve Türkçe kullanım kılavuzu bulunuyor mu?","Tüm kişisel koruyucular laboratuvardan çıkarken çıkarılıyor, gerektiğinde uygun yöntemlerle temizleniyor ve uygun bir ortamda muhafaza ediliyor mu?","Tüm çalışanların laboratuvar önlükleri mevcut mu ve kullanılıyor mu?","Tek kullanımlık KKD' ler güvenli şekilde atılıyor mu?","Tek kullanımlık olmayan koruyucular periyodik olarak kontrol ediliyor ve gerektiğinde yenileriyle değiştiriliyor mu?","Radyoaktivite içeren işlemler bulunması durumda çalışanlar uygun kıyafetler ve kişisel koruyucu donanımları kullanıyor mu?"]},{"title":"PSİKOSOSYAL ETKENLER","subHeader":"","items":["Çalışanlar ile işveren(ler) arasında iyi bir iletişim sürdürülüyor mu?","Çalışanlar; yetki, sorumluluk ve çalışma hedeflerini net olarak biliyor mu?","Çalışanlara, görev ve sorumlulukları haricinde talimat verilmesi engelleniyor mu?"]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş ve periyodik kontrolleri yaptırılıyor mu?","İş kazaları ve meslek hastalıkları vakaları Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Daha önce meydana gelmiş kazalar incelenerek kayıt altına alınıyor, tehlike kaynakları tespit edilerek ileride benzer kazalar ile karşılaşmamak için gerekli önlemler alınıyor mu?","Çalışanların sıcak yüzeyle ya da püsküren buharla temas edip yanması gibi tehlikelere karşı önlemler alınıyor mu?","Laboratuvar ortamında bulunan biyolojik, kimyasal veya fiziksel etkenlerden etkilendiği düşünülen çalışanlar, işyeri hekimi tarafından derhal kontrol ediliyor mu?","Laboratuvar ortamında bulunan biyolojik, kimyasal veya fiziksel etkenlerden etkilenebileceği düşünülen çalışanların aşıları yaptırılıyor mu?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Tüm çalışanlara enfeksiyon riskini azaltmak için genel hijyen bilgisi verilmiş ve gerekli önlemler alınmış mı?","Çalışanlar iş sağlığı ve güvenliği konusunda eğitim almışlar mı?","Çalışanlar yaptıkları işle ilgili olarak gerekli eğitim ve bilgiye sahip mi?","Çalışanlar biyolojik etkenlerle çalışma sırasında maruz kalabileceği riskler konusunda bilgilendiriliyor mu?","Çalışanlar tehlikeli kimyasallarla çalışma sırasında maruz kalınabilecek riskler ve kimyasallar ile güvenli çalışma konusunda bilgilendiriliyor mu?","Çalışanlar kesilme, batma, yanma vb. nedenler ile oluşan yaralara hangi durumda ve kim tarafından müdahale edileceği konusunda bilgilendiriliyor mu?","Çalışanlar kullandıkları makine, araç ve gereçlerin güvenli kullanımı konusunda eğitiliyor mu?","Çalışanlar güvenlik ve sağlık işaretlerinin anlamları konusunda eğitilmiş mi?","Eğitim ve bilgilendirme ile ilgili belgeler kayıt altına alınıyor ve kayıtlar uygun şekilde muhafaza ediliyor mu?"]}]},{"templateId":"isg_mutfak_lokanta_kontrol","title":"MUTFAK/LOKANTA/PASTANELER İÇİN KONTROL LİSTESİ","runningHeader":"MUTFAK/LOKANTA/PASTANELER İÇİN KONTROL LİSTESİ","shortName":"Mutfak / Lokanta / Pastaneler Kontrol Listesi (72 Madde)","layoutType":"ISG_TOPIC_ACTION_TABLE","isLandscape":true,"headerStyle":"TOPIC_COL","formNo":"MTF-01","dosyaNo":"İSG-KL-10","sayfaNo":"1-N","actionHeaderLabel":"Alınması Gereken Önlem","dueDateHeaderLabel":"Tamamlanacağı Tarih","footnote":"* Bu kontrol listesi, 6331 sayılı Kanunun “İşverenin genel yükümlülüğü” başlıklı 4 üncü maddesi birinci fıkrasının (c) bendi uyarınca işverenlerin yapmak/yaptırmak ile yükümlü oldukları risk değerlendirmesi çalışması yerine geçmez ancak çalışma ortamının iyileştirilmesine yönelik adımlar içerir.","sections":[{"title":"GENEL","subHeader":"","items":["Zemin kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplı olup ve iç ve dış zeminler (mekân girişi, merdivenler vs.)düzenli olarak kontrol ediliyor mu?","Zeminde çökme, erime vb. deformasyonlar giderilmiş mi?","Merdiven genişlikleri ve basamak yükseklikleri uygun mu?","Merdivenler boyunca tırabzanlar mevcut olup tırabzan ayakları arasında uygun aralıklarla dikmeler veya düşmeyi önleyecek kapalı bloklar mevcut mu?","Temizlik yapılan alanda kaymayı önlemek için gerekli tedbirler alınıyor mu?","Tütün (sigara) kullanımı kapalı alanlarda yasak mı?","Çatıdan, duvarlardan ya da zeminden su sızıntısı engellendi mi?","Pencere alanı yeterince büyük mü? Doğal aydınlatmadan yeterince faydalanılıyor mu?","Cam yüzeyler üzerinde kırık veya çatlak bulunmamakta ve uygun şekilde monte edilmiş mi?","Çöpler düzenli olarak ve uygun şekilde toplanıyor mu?","Tuvalet ve lavabolar düzenli olarak temizleniyor mu?","Temiz hava akımı bulunmakla beraber tüm alanlar düzenli olarak havalandırılıyor mu?"]},{"title":"ÇALIŞMA ORTAMI","subHeader":"","items":["Tüm alanlarda yeterli aydınlatma sağlanmış ve aydınlatmalar çalışır halde bulunuyor mu?","Çalışanlar, işlerini bitirdikten sonra bütün malzemeleri yerlerine yerleştiriyorlar mı?","Tüm alanların iç düzenlemesi yapılmış, eşya veya malzemelerin kolay ulaşılabilir olması sağlanıyor mu?","Çalışma ortamında, hastalıklara sebebiyet vererek işe devamsızlığa neden olabilecek koşullar önleniyor mu?","Çalışma ortamı sıcaklığı normal seviyelerde mi?","Servis alanı ile mutfak arasındaki geçiş yolları çalışanların kapılara ya da diğer meslektaşlarına çarpma riski oluşturmayacak şekilde iyi düzenlendi mi?","Çalışanların sıcak yüzeyle ya da püsküren buharla temas edip yanması gibi tehlikeler önleniyor mu?","Mutfak malzemeleri uygun şekilde depolanıyor mu? Çalışanların malzemeleri kendi üzerlerine devirmemeleri sağlandı mı?","Makine ve donanımlardan kaynaklanan gürültü yasal sınırlar içinde mi?","Makine ve donanımlardan kaynaklanan titreşim yasal sınırlar içinde mi?"]},{"title":"KESİCİ VE DELİCİ ALETLER (bıçak, satır vb.)","subHeader":"","items":["Kesici ve delici aletler sadece bu konuda yetkili olan çalışanlar tarafından mı kullanılıyor?","Bu tür alet veya ekipmanlar kullanıldıktan sonra yerlerine kaldırılıyor mu?","Kesici veya delici alet veya ekipmanlar periyodik olarak kontrol ediliyor mu?"]},{"title":"HİJYEN","subHeader":"","items":["Tüm alet ve gereçlerin kullanımında gerekli hijyen şartları sağlanıyor mu?","Çalışma esnasında kullanılan veya müşterilerin kullandığı malzemelerin steril biçimde temizlikleri yapılıyor mu?","Çalışanlar eldiven, bone ve gerekli olan diğer koruyucu giysileri temin ediyorlar mı?","Tüm çalışanlara enfeksiyon riskini azaltmak için genel hijyen bilgisi verildi ve gerekli önlemler alındı mı?"]},{"title":"ELEKTRİK","subHeader":"","items":["Çalışmalar sırasında kullanılan kablolu aletler takılma veya düşmeyi önleyecek şekilde kullanılıyor mu?","Kaçak akım rölesi ana elektrik hattına bağlı mı?","Tüm sigortaların korunaklı yerlerde olması sağlandı mı?","Elektrik/sigorta kutuları kilitlenmiş, yetkisiz kişilerin erişimleri önlendi mi?","Açıkta kablo bulunmuyor ve prizlerin sağlamlığı düzenli olarak kontrol ediliyor mu?","Elektrikli ekipmanlar düzenli olarak kontrol edilmekle beraber bozuk veya arızalı ekipmanların kullanımı engelleniyor mu?"]},{"title":"MAKİNA, ARAÇ VE GEREÇLER","subHeader":"","items":["Makinaların hareketli parçaları koruma altına alındı mı?","Dilimleme ve doğrama araçları üzerinde güvenlik korumaları bulunuyor mu?","Makinalar kazara/istemeden çalışmamakta ve acil durdurma mekanizmaları bulunmakta mı?","Makinaları doğru kullanımı ve bakımı konusunda kullanım kılavuzları bulunuyor ve bu kılavuzlara uygun olarak kullanılıyorlar mı?","Makina ve ekipmanların elektrik aksamına su veya diğer sıvıların temas ettirilmesi önlendi mi?","Sıcak sıvıların sıçramasına karşı uygun nitelikte eldiven ve iş elbisesi kullanılıyor mu?","Sıcak yağ ve sıvı içeren ekipmanlar kullanılmıyorken kapalı şekilde tutulmakta mı?"]},{"title":"YANGIN VE ACİL DURUMLAR","subHeader":"","items":["Çalışanların ateşle çalışmasından doğan herhangi bir yangın ya da patlama riskinin oluşması engelleniyor mu?","Gaz kaçağına karşı gerekli önlemler alındı mı?","Havlu, peçete, elbezi gibi tutuşma tehlikesi olan eşyalar ocak ve fırınlardan uzak yerlerde tutuluyor mu?","Kimyasal içerikleri nedeniyle alevlenebilir ürünler ya da basınçlı kaplar (gaz tüpleri, basınçlı pişirme kapları gibi); ısı, ışık ve diğer malzemelerden uzakta ve malzeme güvenlik formuna/ talimatlara uygun şekilde muhafaza ediliyor ve kullanılıyor mu?","Kapı ve kaçış yollarını gösteren acil durum levhaları uygun yerlere yerleştirildi mi?","Acil duruma neden olan olaya ilişkin (yangın, gaz kaçağı, deprem vb.) telefon numaraları görünür yer(ler)e asıldı mı?","Yeterli sayıda yangın söndürücü mevcut mu? Son kullanma tarihleri ve basınçları kontrol ediliyor mu?","Tutuşma ya da dumanın geri tepmesi tehlikesi barındıran aspiratör ve bacalar (is, kurum vb. birikmeler için) düzenli olarak temizlenmektedir.","Tüm çalışanlar yangın güvenliği ve acil durum planı hakkında bilgilendirildi mi?","İçerisinde yeterli malzeme bulunan ilkyardım dolabı bulunuyor mu?"]},{"title":"ELLE TAŞIMA VE ERGONOMİ","subHeader":"","items":["Ağır yüklerin elle kaldırılması ve taşınması önleniyor mu?","Yüklerin kaldırılması, servis arabası gibi ekipmanların itilmesi veya çekilmesi uygun pozisyonlarda mı yapılıyor?","Çalışma ortamında çalışanların uygunsuz pozisyonlarda çalışmasını gerektiren durumlar önleniyor mu?","Çalışanlar işlerini yaparken çok uzak mesafelere uzanmaları önleniyor mu?","Çalışanlar uzun süre aynı pozisyonda çalışmaları önleniyor mu?","İşyerinin çalışma alanı rahat mı? Güvenli olarak çalışmalarını sağlayabilecek yeterli boş alan var mı?","Ağır yüklerin uygunsuz şekilde kaldırılmasını, itilmesini ya da çekilmesini önleyecek kaldırma tertibatı var mı?","Sıcak mutfak malzemelerinin taşınmasında ısıya dayanıklı eldivenler kullanılıyor mu?"]},{"title":"PSİKOSOSYAL ETKENLER","subHeader":"","items":["Çalışanların görev tanımları yapıldı mı? İlave iş yükü oluşması engelleniyor mu?","Çalışma koşullarının iyileştirilmesine yönelik uygulamalara çalışanların katılımı sağlanıyor mu?","Çalışanlar, idarecilerinden ve deneyimli çalışma arkadaşlarından gerekli bilgi ve desteği alıyor mu?","Çalışanların müşteriler tarafından tehdit edilme, şiddete maruz kalma ve aşağılanması durumunda, yapması gerekenler ve alınan önlemler belirlendi mi?"]},{"title":"KAZALAR VE HASTALIKLAR","subHeader":"","items":["Çalışanların işe giriş raporları ve periyodik kontrolleri yaptırılıyor mu?","İş kazaları ve meslek hastalıkları vakaları Sosyal Güvenlik Kurumuna rapor ediliyor mu?","Çalışanların karşı karşıya kaldıkları önceden olmuş kazalar veya işe bağlı hastalıklar (düşme, yaralanma, yanık, ıslak çalışma nedeniyle cilt rahatsızlıkları vb.) incelenerek yeniden meydana gelmeleri önlenmekte mi?","Paket servis yapan çalışanlar, araç kullanırken her türlü güvenlik tedbirlerine uymaları konusunda talimat verildi mi?"]},{"title":"EĞİTİM VE BİLGİLENDİRME","subHeader":"","items":["Çalışanlar iş sağlığı ve güvenliği konusunda eğitilmiş ve gerekli talimatlar verildi mi?","Çalışanlar yaptıkları işle ilgili olarak yeterli bilgiye sahip mi?","İlgili tüm çalışanlar mutfak araçları ve makinalarının doğru kullanılması konusunda eğitildi ve bilgilendirildi mi?","Eğitim ve bilgilendirme ile ilgili belgeler kayıt altına alınıyor ve kayıtlar uygun şekilde muhafaza ediliyor mu?"]}]}];
